## File 3: `src/middleware.js` — Middleware Layer

```javascript
/**
 * ============================================================================
 * SECTION: MIDDLEWARE
 * ============================================================================
 *
 * WHY middleware? Express processes requests through a pipeline of functions.
 *   - Logging middleware gives us visibility into every request (educational + debug).
 *   - JSON parsing is required so POST/PUT bodies are readable as objects.
 *   - The error-handling middleware sits at the END of the pipeline and catches
 *     any error thrown by routes or previous middleware.
 *
 * Express identifies error-handling middleware by its signature:
 *   (err, req, res, next) =>  — note the FOUR parameters.
 */

const { AppError } = require('./errors');

/**
 * Request logger middleware.
 * Logs method, URL, and timestamp for every incoming request.
 * This is purely observational — it calls next() to continue the pipeline.
 *
 * @param {import('express').Request} req
 * @param {import('express').Response} res
 * @param {Function} next
 */
function requestLogger(req, res, next) {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.originalUrl}`);
  next(); // Pass control to the next middleware/route handler.
}

/**
 * Global error-handling middleware.
 * Catches all errors (thrown or passed via next(err)) and sends a consistent JSON response.
 *
 * @param {Error} err - The error object (should be an AppError instance).
 * @param {import('express').Request} req
 * @param {import('express').Response} res
 * @param {Function} next
 */
function errorHandler(err, req, res, next) {
  // If the error is NOT operational, it's a programmer bug — log the full stack.
  if (!err.isOperational) {
    console.error('❌ UNCAUGHT ERROR:', err.stack);
  }

  // Default to 500 for unexpected errors; use err.statusCode if provided.
  const statusCode = err.statusCode || 500;

  // Build a consistent JSON error response shape.
  const errorResponse = {
    success: false,
    error: {
      message: err.message,
      ...(err.messages && { details: err.messages }), // Include validation details if present.
    },
  };

  res.status(statusCode).json(errorResponse);
}

module.exports = { requestLogger, errorHandler };
```

**Why this pattern?** The four-parameter signature `(err, req, res, next)` is Express's convention for error middleware. It only runs when an error is passed down the chain — normal requests skip it entirely. This separation keeps happy-path code clean.

