## File 4: `src/routes/books.js` — Book CRUD Routes

```javascript
/**
 * ============================================================================
 * SECTION: BOOK ROUTES
 * ============================================================================
 *
 * WHY separate route file? Separation of concerns: routes know about URLs and
 *   HTTP methods, but NOT about app setup or error middleware. This makes the
 *   codebase modular and testable.
 *
 * WHY in-memory array? For this educational example it eliminates database
 *   complexity while still demonstrating full CRUD. In production you'd swap
 *   this for a real data layer (PostgreSQL, MongoDB, etc.).
 *
 * REST conventions used:
 *   - GET    /books          → list all (with optional query filters)
 *   - GET    /books/:id      → get one by ID
 *   - POST   /books          → create new
 *   - PUT    /books/:id      → full update
 *   - DELETE /books/:id      → delete
 *
 * HTTP status codes:
 *   - 200 OK        → successful GET/PUT
 *   - 201 Created   → successful POST
 *   - 204 No Content→ successful DELETE (no body)
 *   - 400 Bad Request → validation error
 *   - 404 Not Found → resource doesn't exist
 *   - 409 Conflict  → duplicate resource
 */

const { Router } = require('express');
const { NotFoundError, ValidationError } = require('../errors');

// Create a router instance — this isolates our book routes.
const router = Router();

// ============================================================================
// DATA LAYER: In-Memory Storage
// ============================================================================
//
// WHY an array of objects? Simple, ordered, and easy to filter/sort.
// Each book has:
//   - id: unique string identifier (we generate with a counter for simplicity)
//   - title, author, genre: core bibliographic fields
//   - publishedYear: integer year
//   - createdAt / updatedAt: ISO timestamps for auditability
//
// In production, this would be replaced by database queries.
let books = [
  {
    id: '1',
    title: 'The Pragmatic Programmer',
    author: 'David Thomas, Andrew Hunt',
    genre: 'Technology',
    publishedYear: 1999,
    createdAt: '2024-01-01T00:00:00.000Z',
    updatedAt: '2024-01-01T00:00:00.000Z',
  },
  {
    id: '2',
    title: 'Dune',
    author: 'Frank Herbert',
    genre: 'Science Fiction',
    publishedYear: 1965,
    createdAt: '2024-01-01T00:00:00.000Z',
    updatedAt: '2024-01-01T00:00:00.000Z',
  },
];

// Simple ID generator — in production use UUID or database auto-increment.
let nextId = 3;

/**
 * Generate a unique string ID.
 * @returns {string} Unique ID.
 */
function generateId() {
  return String(nextId++);
}

// ============================================================================
// VALIDATION HELPERS
// ============================================================================

/**
 * Validate required fields for creating or updating a book.
 * Returns an array of error messages (empty = valid).
 *
 * @param {object} body - The request body to validate.
 * @returns {string[]} Array of validation error messages.
 */
function validateBook(body) {
  const errors = [];

  if (!body.title || typeof body.title !== 'string' || body.title.trim() === '') {
    errors.push('title is required and must be a non-empty string');
  }
  if (!body.author || typeof body.author !== 'string' || body.author.trim() === '') {
    errors.push('author is required and must be a non-empty string');
  }
  if (!body.genre || typeof body.genre !== 'string' || body.genre.trim() === '') {
    errors.push('genre is required and must be a non-empty string');
  }
  if (
    body.publishedYear === undefined ||
    body.publishedYear === null ||
    !Number.isInteger(body.publishedYear) ||
    body.publishedYear < 0 ||
    body.publishedYear > new Date().getFullYear() + 1
  ) {
    errors.push('publishedYear is required and must be a valid integer year');
  }

  return errors;
}

// ============================================================================
// ROUTE HANDLERS
// ============================================================================

/**
 * GET /books
 * List all books with optional filtering by genre, author, or publishedYear.
 *
 * Query parameters (all optional):
 *   - genre: filter by exact genre match
 *   - author: filter by author name substring (case-insensitive)
 *   - publishedYear: filter by exact year
 *
 * Example: GET /books?genre=Science+Fiction&publishedYear=1965
 *
 * @param {import('express').Request} req
 * @param {import('express').Response} res
 */
router.get('/', (req, res) => {
  let result = books;

  // Apply filters if query parameters are provided.
  const { genre, author, publishedYear } = req.query;

  if (genre) {
    result = result.filter((book) => book.genre.toLowerCase() === genre.toLowerCase());
  }
  if (author) {
    result = result.filter((book) =>
      book.author.toLowerCase().includes(author.toLowerCase())
    );
  }
  if (publishedYear) {
    const year = parseInt(publishedYear, 10);
    if (!isNaN(year)) {
      result = result.filter((book) => book.publishedYear === year);
    }
  }

  // Return the (possibly filtered) list with a 200 status.
  res.status(200).json({ success: true, count: result.length, data: result });
});

/**
 * GET /books/:id
 * Retrieve a single book by its ID.
 *
 * @param {import('express').Request} req — req.params.id is the book ID.
 * @param {import('express').Response} res
 * @param {Function} next — passed to on error.
 */
router.get('/:id', (req, res, next) => {
  const book = books.find((b) => b.id === req.params.id);

  if (!book) {
    // Throw a NotFoundError so the global error middleware handles it.
    return next(new NotFoundError('Book', req.params.id));
  }

  res.status(200).json({ success: true, data: book });
});

/**
 * POST /books
 * Create a new book. Expects JSON body with title, author, genre, publishedYear.
 *
 * Example request body:
 *   { "title": "1984", "author": "George Orwell", "genre": "Dystopian", "publishedYear": 1949 }
 *
 * @param {import('express').Request} req
 * @param {import('express').Response} res
 * @param {Function} next
 */
router.post('/', (req, res, next) => {
  const validationErrors = validateBook(req.body);

  if (validationErrors.length > 0) {
    return next(new ValidationError(validationErrors));
  }

  const now = new Date().toISOString();
  const newBook = {
    id: generateId(),
    title: req.body.title.trim(),
    author: req.body.author.trim(),
    genre: req.body.genre.trim(),
    publishedYear: parseInt(req.body.publishedYear, 10),
    createdAt: now,
    updatedAt: now,
  };

  books.push(newBook);

  // 201 Created is the correct status for a newly created resource.
  res.status(201).json({ success: true, data: newBook });
});

/**
 * PUT /books/:id
 * Full update of an existing book. Replaces all fields.
 *
 * @param {import('express').Request} req
 * @param {import('express').Response} res
 * @param {Function} next
 */
router.put('/:id', (req, res, next) => {
  const bookIndex = books.findIndex((b) => b.id === req.params.id);

  if (bookIndex === -1) {
    return next(new NotFoundError('Book', req.params.id));
  }

  const validationErrors = validateBook(req.body);
  if (validationErrors.length > 0) {
    return next(new ValidationError(validationErrors));
  }

  const now = new Date().toISOString();
  books[bookIndex] = {
    id: req.params.id, // ID never changes.
    title: req.body.title.trim(),
    author: req.body.author.trim(),
    genre: req.body.genre.trim(),
    publishedYear: parseInt(req.body.publishedYear, 10),
    createdAt: books[bookIndex].createdAt, // Preserve original creation time.
    updatedAt: now,
  };

  res.status(200).json({ success: true, data: books[bookIndex] });
});

/**
 * DELETE /books/:id
 * Delete a book by ID. Returns 204 No Content on success.
 *
 * @param {import('express').Request} req
 * @param {import('express').Response} res
 * @param {Function} next
 */
router.delete('/:id', (req, res, next) => {
  const bookIndex = books.findIndex((b) => b.id === req.params.id);

  if (bookIndex === -1) {
    return next(new NotFoundError('Book', req.params.id));
  }

  // Remove the book from the array.
  books.splice(bookIndex, 1);

  // 204 No Content is standard for DELETE with no response body.
  res.status(204).send();
});

module.exports = router;
```

**Why these patterns?**
- **`next(err)` pattern**: Instead of nested if/else chains, we throw errors and let middleware handle them. This keeps route handlers focused on business logic.
- **`splice()` for delete**: Simple array mutation — fine for in-memory, but a database would use `DELETE FROM books WHERE id = ?`.
- **Preserving `createdAt` on update**: Good practice — creation time should never change, only `updatedAt`.

