## File 5: `src/routes/stats.js` — Statistics Endpoint

```javascript
/**
 * ============================================================================
 * SECTION: STATISTICS ROUTE
 * ============================================================================
 *
 * WHY a separate stats endpoint? It's a read-only aggregate view of the data.
 *   Keeping it separate from CRUD routes follows the single-responsibility
 *   principle and makes the API easier to navigate.
 *
 * This endpoint answers questions like:
 *   - How many books do we have?
 *   - What genres exist and how many books per genre?
 *   - Who are the most prolific authors?
 */

const { Router } = require('express');
const router = Router();

/**
 * GET /stats
 * Return aggregate statistics about the book collection.
 *
 * Response shape:
 *   {
 *     totalBooks: number,
 *     genres: { [genreName]: count },
 *     authors: { [authorName]: count },
 *     oldestBook: { title, publishedYear },
 *     newestBook: { title, publishedYear }
 *   }
 *
 * @param {import('express').Request} req
 * @param {import('express').Response} res
 */
router.get('/', (req, res) => {
  const totalBooks = books.length;

  // Build genre counts.
  const genres = {};
  for (const book of books) {
    genres[book.genre] = (genres[book.genre] || 0) + 1;
  }

  // Build author counts.
  const authors = {};
  for (const book of books) {
    authors[book.author] = (authors[book.author] || 0) + 1;
  }

  // Find oldest and newest by publishedYear.
  let oldestBook = null;
  let newestBook = null;

  if (totalBooks > 0) {
    oldestBook = books.reduce(
      (min, book) => (book.publishedYear < min.publishedYear ? book : min),
      books[0]
    );
    newestBook = books.reduce(
      (max, book) => (book.publishedYear > max.publishedYear ? book : max),
      books[0]
    );
  }

  res.status(200).json({
    success: true,
    data: {
      totalBooks,
      genres,
      authors,
      oldestBook: oldestBook
        ? { title: oldestBook.title, publishedYear: oldestBook.publishedYear }
        : null,
      newestBook: newestBook
        ? { title: newestBook.title, publishedYear: newestBook.publishedYear }
        : null,
    },
  });
});

module.exports = router;
```

**Why `reduce()` for min/max?** It's a single-pass O(n) operation — cleaner than sorting the entire array just to find extremes. For large datasets you'd use a database aggregate query instead.

