    id: 'b2c3d4e5-f6a7-8901-bcde-f12345678901',
    title: 'To Kill a Mockingbird',
    author: 'Harper Lee',
    genre: 'Fiction',
    publishedYear: 1960,
    rating: 4.8,
  },
  {
    id: 'c3d4e5f6-a7b8-9012-cdef-123456789012',
    title: 'A Brief History of Time',
    author: 'Stephen Hawking',
    genre: 'Science',
    publishedYear: 1988,
    rating: 4.7,
  },
