 * @param {Object} bookData - The raw book data from the request body.
 * @param {string} bookData.title - Book title (required).
 * @param {string} bookData.author - Author name (required).
 * @param {string} [bookData.genre] - Genre of the book (optional, defaults to 'Unknown').
 * @param {number} [bookData.publishedYear] - Year published (optional).
 * @param {number} [bookData.rating] - Rating from 0-5 (optional, defaults to 0).
