/**
 * Finds a single book by its UUID.
 *
 * @param {string} id - The UUID of the book to find.
 * @returns {Book|undefined} The book if found, otherwise undefined.
 */
function getBookById(id) {
  return books.find((book) => book.id === id);
}

/**
 * Adds a new book to in-memory storage.
 *
 * @param {Book} book - The book object to add.
 * @returns {Book} The added book (for confirmation).
 */
function addBook(book) {
