  return book;
}

/**
 * Updates an existing book by ID with the provided fields.
 * Only updates fields that are explicitly provided (partial update / PATCH behavior).
 *
 * @param {string} id - The UUID of the book to update.
 * @param {Object} updates - Fields to update.
 * @returns {Book|undefined} The updated book, or undefined if not found.
