function updateBook(id, updates) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return undefined;

  // Merge: keep existing values for fields not provided in updates
  books[index] = { ...books[index], ...updates };
  return books[index];
}

/**
 * Deletes a book by its UUID.
 *
 * @param {string} id - The UUID of the book to delete.
 * @returns {boolean} True if the book was found and deleted, false otherwise.
 */
function deleteBook(id) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return false;

  books.splice(index, 1); // Remove exactly one element at the given index
  return true;
}

/**
 * Returns statistics about the book collection.
 * Computes count, average rating, and genre distribution on the fly.
 *
 * @returns {Object} Statistics object containing:
 *   - totalBooks: number of books
 *   - averageRating: mean rating across all books (rounded to 2 decimals)
 *   - genres: record mapping each genre to its book count
 *   - oldestBook: title and year of the earliest published book
 *   - newestBook: title and year of the most recently published book
 */
function getStats() {
  const totalBooks = books.length;

  // Guard against empty collection to avoid division by zero
  if (totalBooks === 0) {
    return {
      totalBooks: 0,
      averageRating: 0,
      genres: {},
      oldestBook: null,
      newestBook: null,
    };
  }

  // Calculate average rating using reduce for functional style
  const totalRating = books.reduce((sum, book) => sum + book.rating, 0);
  const averageRating = Math.round((totalRating / totalBooks) * 100) / 100; // Round to 2 decimals

  // Build genre distribution map
  const genres = {};
  for (const book of books) {
    genres[book.genre] = (genres[book.genre] || 0) + 1;
