  // Find oldest and newest by publishedYear (nulls sort to end in ascending order)
  const sortedByYear = [...books].sort((a, b) => {
    if (a.publishedYear === null) return 1;
    if (b.publishedYear === null) return -1;
    return a.publishedYear - b.publishedYear;
  });

  return {
    totalBooks,
    averageRating,
    genres,
    oldestBook: sortedByYear[0]
      ? { title: sortedByYear[0].title, year: sortedByYear[0].publishedYear }
      : null,
    newestBook: sortedByYear[sortedByYear.length - 1]
      ? { title: sortedByYear[sortedByYear.length - 1].title, year: sortedByYear[sortedByYear.length - 1].publishedYear }
      : null,
  };
}

