/**
 * ============================================================================
 * ERROR HANDLING MIDDLEWARE
 * ============================================================================
 *
 * Express middleware is a function that has access to the request (req),
 * response (res), and the next middleware function (next). Middleware runs
 * in the order it is defined, so error-handling middleware must be placed
 * AFTER all route definitions.
 *
 * WHY CUSTOM ERROR CLASSES?
 * -------------------------
 * Custom error classes let us attach a `statusCode` property so our single
 * error handler can automatically set the correct HTTP response code without
 * checking error types with instanceof everywhere. This is cleaner than
 * returning { status, message } from every route.
 *
 * ERROR HANDLING PATTERN:
 *   1. Route handlers call next(error) when something goes wrong.
 *   2. A dedicated error-handling middleware (with 4 parameters: err, req, res, next)
 *      catches all thrown/passed errors in one place.
 *   3. In production, you'd log `err` to a logging service instead of sending it
 *      to the client (to avoid leaking stack traces).
 */

/**
 * Custom error class for validation failures (400 Bad Request).
 * Attaches HTTP status code so the global handler can use it automatically.
 */
class ValidationError extends Error {
  /**
   * @param {string} message - Human-readable description of the validation failure.
   */
  constructor(message) {
    super(message);
    this.name = 'ValidationError';
    this.statusCode = 400; // HTTP 400: The server cannot process the request due to client error
  }
}

/**
 * Custom error class for resource-not-found cases (404 Not Found).
 */
class NotFoundError extends Error {
  /**
   * @param {string} resource - Name of the resource that was not found (e.g., 'Book').
   * @param {string} id - The ID that was searched for.
   */
  constructor(resource, id) {
    super(`${resource} with id "${id}" not found`);
    this.name = 'NotFoundError';
    this.statusCode = 404; // HTTP 404: The requested resource does not exist
  }
}

/**
 * Custom error class for duplicate resource cases (409 Conflict).
 */
class DuplicateError extends Error {
  /**
   * @param {string} message - Description of the duplication conflict.
   */
  constructor(message) {
    super(message);
    this.name = 'DuplicateError';
    this.statusCode = 409; // HTTP 409: Request conflicts with current state
  }
}

/**
 * Global error-handling middleware.
 *
 * Express identifies this as an error handler because it has FOUR parameters:
 * (err, req, res, next). Regular middleware only has three (req, res, next).
 *
 * This middleware:
 *   1. Sets the HTTP status from err.statusCode (or defaults to 500).
 *   2. Returns a JSON error response with message and type.
 *   3. In development, also includes the stack trace for debugging.
 *
 * @param {Error} err - The error object passed via next(err) or thrown.
 * @param {import('express').Request} req - The Express request object.
 * @param {import('express').Response} res - The Express response object.
 * @param {import('express').NextFunction} next - The next middleware function.
 */
function errorHandler(err, req, res, next) {
  // Log the full error to console (in production, use a proper logger like Winston)
  console.error(`[ERROR] ${err.name}: ${err.message}`);
  if (process.env.NODE_ENV !== 'production' && err.stack) {
    console.error(err.stack);
  }

  // Determine status code: use the error's statusCode if set, otherwise 500
  const statusCode = err.statusCode || 500;

  // Build a consistent JSON error response shape
  res.status(statusCode).json({
    success: false,
    error: {
      type: err.name,
      message: err.message,
      // Only include stack in non-production for security
      ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
    },
  });
}

module.exports = {
  ValidationError,
  NotFoundError,
  DuplicateError,
  errorHandler,
};
