const { ValidationError, NotFoundError } = require('../middleware/errorHandler');

/**
 * Validates that the required fields for creating a book are present and valid.
 *
 * @param {Object} data - The request body containing book data.
 * @throws {ValidationError} If title or author is missing or invalid.
 */
function validateCreateBook(data) {
  if (!data.title || typeof data.title !== 'string' || data.title.trim() === '') {
    throw new ValidationError('Title is required and must be a non-empty string');
  }
  if (!data.author || typeof data.author !== 'string' || data.author.trim() === '') {
    throw new ValidationError('Author is required and must be a non-empty string');
  }
  if (data.rating !== undefined && (typeof data.rating !== 'number' || data.rating < 0 || data.rating > 5)) {
    throw new ValidationError('Rating must be a number between 0 and 5');
  }
  if (data.publishedYear !== undefined && (!Number.isInteger(data.publishedYear) || data.publishedYear < 0 || data.publishedYear > new Date().getFullYear() + 1)) {
    throw new ValidationError('Published year must be a valid integer');
  }
}

/**
 * Retrieves all books, optionally filtered by query parameters.
 *
 * Supported filters (via GET /books?genre=Fiction&minRating=4&search=gatsby):
 *   - genre: exact match on genre (case-insensitive)
 *   - minRating: minimum rating threshold
 *   - search: substring search across title and author (case-insensitive)
 *
 * @param {Object} filters - Query parameters from req.query.
 * @returns {Array<Book>} Filtered list of books.
 */
function findAllBooks(filters = {}) {
  let result = getAllBooks();

  // Apply genre filter if provided
  if (filters.genre) {
    const genreLower = filters.genre.toLowerCase();
    result = result.filter((book) => book.genre.toLowerCase() === genreLower);
  }

  // Apply minimum rating filter if provided
  if (filters.minRating !== undefined) {
    const minRating = parseFloat(filters.minRating);
    result = result.filter((book) => book.rating >= minRating);
  }

  // Apply search filter across title and author if provided
  if (filters.search) {
    const searchLower = filters.search.toLowerCase();
    result = result.filter(
      (book) =>
        book.title.toLowerCase().includes(searchLower) ||
        book.author.toLowerCase().includes(searchLower)
    );
  }

  return result;
}

/**
 * Retrieves a single book by ID, throwing NotFoundError if not found.
 *
 * @param {string} id - The UUID of the book.
 * @returns {Book} The found book.
 * @throws {NotFoundError} If no book exists with the given ID.
 */
function findBookById(id) {
  const book = getBookById(id);
  if (!book) {
    throw new NotFoundError('Book', id);
  }
  return book;
}

/**
 * Creates a new book after validating input.
 *
 * @param {Object} bookData - The book data from the request body.
 * @returns {Book} The newly created book.
 * @throws {ValidationError} If input fails validation.
 */
function createNewBook(bookData) {
  validateCreateBook(bookData);

  const newBook = createBook(
    bookData.title.trim(),
    bookData.author.trim(),
    bookData.genre,
    bookData.publishedYear,
    bookData.rating
  );

  addBook(newBook);
  return newBook;
}

/**
 * Updates an existing book by ID with partial data.
 *
 * @param {string} id - The UUID of the book to update.
 * @param {Object} updates - Fields to update (any subset of book fields).
 * @returns {Book} The updated book.
 * @throws {NotFoundError} If the book doesn't exist.
 * @throws {ValidationError} If updated fields fail validation.
 */
function updateExistingBook(id, updates) {
  // First, verify the book exists
  const existingBook = getBookById(id);
  if (!existingBook) {
    throw new NotFoundError('Book', id);
  }

  // Validate any provided fields that we know how to validate
  if (updates.title !== undefined || updates.author !== undefined) {
    // Build a minimal data object for validation
    const validationData = {
      title: updates.title ?? existingBook.title,
      author: updates.author ?? existingBook.author,
      rating: updates.rating,
      publishedYear: updates.publishedYear,
    };
    validateCreateBook(validationData);
  }

  const updatedBook = updateBook(id, updates);
  return updatedBook;
}

/**
 * Deletes a book by ID.
 *
 * @param {string} id - The UUID of the book to delete.
 * @returns {boolean} True if deleted successfully.
 * @throws {NotFoundError} If the book doesn't exist.
 */
function deleteExistingBook(id) {
  const existingBook = getBookById(id);
  if (!existingBook) {
    throw new NotFoundError('Book', id);
  }

  return deleteBook(id);
}

/**
 * Returns statistics about the book collection.
 *
 * @returns {Object} Statistics object.
 */
function getBookStats() {
  return getStats();
}

