  res.end = function (...args) {
    const duration = Date.now() - start;
    console.log(`[${req.method}] ${req.originalUrl} — ${res.statusCode} — ${duration}ms`);
    originalEnd.apply(res, args);
  };
  next();
});

// ============================================================================
// ROUTE MOUNTING
// ============================================================================

/**
 * Mount book routes at /books.
 * All routes defined in routes/books.js will be prefixed with /books.
 * e.g., router.get('/') becomes GET /books
 */
app.use('/books', bookRoutes);

/**
 * Mount stats routes at /stats.
 */
app.use('/stats', statsRoutes);

// ============================================================================
// ROOT ENDPOINT
// ============================================================================

/**
 * @name GET /
 * @description Returns API information and available endpoints.
 * @success 200 { "name": "...", "version": "...", "endpoints": [...] }
 */
app.get('/', (req, res) => {
  res.json({
    name: 'Book REST API',
    version: '1.0.0',
    description: 'A simple CRUD API for managing books — educational example',
    endpoints: {
      getBooks: 'GET /books',
      getBookById: 'GET /books/:id',
      createBook: 'POST /books',
      updateBook: 'PUT /books/:id',
      deleteBook: 'DELETE /books/:id',
      getStats: 'GET /stats',
    },
  });
});

// ============================================================================
// 404 HANDLER — Catch-all for undefined routes
// ============================================================================

/**
 * Any request that reaches this point hasn't matched any route.
 * We throw a NotFoundError so the global error handler formats it nicely.
 */
app.use((req, res, next) => {
  const { NotFoundError } = require('./middleware/errorHandler');
  next(new NotFoundError('Endpoint', req.originalUrl));
});

// ============================================================================
// GLOBAL ERROR HANDLER
// ============================================================================
// MUST be the last middleware registered.
// Express routes errors here when next(err) is called or an exception is thrown.
app.use(errorHandler);

// ============================================================================
// EXPORT
// ============================================================================
// Export the app so it can be used by server.js (to start listening) and
// also for unit testing with supertest without actually binding a port.
module.exports = app;
```

