## Arquivo 3: `src/middleware/errorHandler.js` — Middleware de Tratamento de Erros

```javascript
/**
 * ============================================================================
 * MIDDLEWARE DE TRATAMENTO DE ERROS
 * ============================================================================
 *
 * POR QUE um middleware centralizado de erros?
 * --------------------------------------------
 * Express possui um mecanismo especial para middlewares de erro: funções com
 * EXATAMENTE 4 parâmetros (err, req, res, next). Quando qualquer rota ou
 * middleware chama next(err) ou lança uma exceção, o Express encaminha a execução
 * para este middleware. Isso evita que precisemos repetir blocos try/catch em
 * cada rota.
 *
 * Padrão async/await + express-async-errors:
 * -------------------------------------------
 * Em rotas assíncronas, erros lançados dentro de callbacks Promise não são
 * capturados automaticamente pelo Express. Por isso, usamos o padrão onde
 * cada handler é envolto para capturar erros e encaminhar para next(err).
 */

const { InternalError } = require("../classes/errors");

/**
 * Middleware principal de tratamento de erros.
 *
 * @param {Error} err - A instância de erro lançada
 * @param {import('express').Request} req - Objeto Request do Express
 * @param {import('express').Response} res - Objeto Response do Express
 * @param {import('express').NextFunction} next - Função next (não utilizada aqui)
 */
function errorHandler(err, req, res, next) {
  // Log completo do erro no servidor para depuração
  // Em produção, envie para um serviço como Sentry ou ELK Stack
  console.error(`[ERROR] ${new Date().toISOString()}`);
  console.error(`  Nome:      ${err.name}`);
  console.error(`  Mensagem:  ${err.message}`);
  console.error(`  Status:    ${err.statusCode || "N/A"}`);
  if (err.stack) {
    console.error(`  Stack:     ${err.stack.split("\n").slice(0, 3).join("\n             ")}`);
  }

  // Determina se é um erro operacional conhecido ou um bug inesperado
  const isOperational = err.isOperational !== false; // undefined também conta como operational
  const statusCode = err.statusCode || 500;

  /**
   * ESTRUTURA DA RESPOSTA DE ERRO:
   * --------------------------------
   * Padronizamos o formato de resposta para erros, facilitando o consumo pelo cliente:
   * {
   *   success: false,
   *   error: {
   *     name: "NotFoundError",
   *     message: "Book com ID 'abc' não encontrado",
   *     statusCode: 404,
   *     timestamp: "2024-01-15T10:30:00.000Z"
   *   }
   * }
   */
  const errorResponse = {
    success: false,
    error: {
      name: err.name,
      message: err.message,
      statusCode,
      timestamp: err.timestamp || new Date().toISOString(),
    },
  };

  // Adiciona detalhes de validação apenas para erros de validação (400)
  if (err.details) {
    errorResponse.error.details = err.details;
  }

  // Para erros operacionais conhecidos, enviamos a resposta padronizada
  if (isOperational) {
    return res.status(statusCode).json(errorResponse);
  }

  // PARA ERROS NÃO-OPERACIONAIS (bugs):
  // Nunca expomos detalhes internos ao cliente. Enviamos uma mensagem genérica.
  // Os detalhes completos ficam apenas nos logs do servidor (console.error acima).
  return res.status(500).json({
    success: false,
    error: {
      name: "InternalError",
      message: "Ocorreu um erro interno no servidor. Nossa equipe foi notificada.",
      statusCode: 500,
      timestamp: new Date().toISOString(),
    },
  });
}

/**
 * ============================================================================
 * FUNÇÃO WRAPPER PARA ROTAS ASSÍNCRONAS
 * ============================================================================
 *
 * POR QUE envolver handlers assíncronos?
 * ---------------------------------------
 * Quando uma função async lança um erro (ex: throw new Error()), ele se torna
 * uma Promise rejeitada. O Express NÃO captura automaticamente rejeições de
 * Promises em middlewares. Esta função wrapper captura o erro e o encaminha
 * para next(err), que por sua vez é tratado pelo middleware errorHandler.
 *
 * Alternativa: usar a biblioteca 'express-async-errors' que patchea o Express.
 * Escolhemos esta abordagem manual para fins educacionais, mostrando o mecanismo
 * por trás do funcionamento.
 */

/**
 * Envelopa um handler assíncrono para capturar erros e encaminhar ao middleware.
 *
 * @param {Function} fn - Função assíncrona do handler (req, res, next) => {}
 * @returns {Function} Handler Express com tratamento de erro embutido
 */
function asyncHandler(fn) {
  return function (req, res, next) {
    // A função retorna uma Promise; .catch() captura rejeições
    fn(req, res, next).catch(next);
    // Nota: ao passar 'next' diretamente no .catch(), o Express encaminha
    // a exceção para o middleware de erro (errorHandler) automaticamente.
  };
}

module.exports = { errorHandler, asyncHandler };
```

**Explicação:** O middleware `errorHandler` é a peça central que garante que **todos** os erros sejam tratados de forma consistente. A distinção entre erros operacionais e não-operacionais é crucial: erros operacionais (como "livro não encontrado") são condições normais do negócio e devem ter respostas claras; erros não-operacionais (bugs) nunca devem expor detalhes internos. A função `asyncHandler` resolve o problema clássico de Promises rejeitadas em rotas Express — sem ela, um `throw` dentro de uma rota async causaria um crash silencioso (unhandled promise rejection).

