## Arquivo 4: `src/data/books.js` — Armazenamento em Memória

```javascript
/**
 * ============================================================================
 * ARMAZENAMENTO EM MEMÓRIA (Array)
 * ============================================================================
 *
 * POR QUE usar um array em vez de um objeto?
 * -------------------------------------------
 * Array vs. Object para armazenamento:
 *   - Arrays mantêm ordem de inserção (útil para listagem cronológica)
 *   - Arrays suportam métodos ricos: filter, map, findIndex, splice
 *   - Busca por ID com findIndex é O(n), mas para dados pequenos (< 1000) é imperceptível
 *   - Em um objeto, precisaríamos de duas estruturas (um Map para IDs + array para ordem)
 *
 * POR QUE não usar um banco de dados real?
 * -----------------------------------------
 * Para este exemplo educacional, um array em memória:
 *   1. Elimina complexidade de configuração (sem conexão com DB)
 *   2. Permite focar nos conceitos de REST, rotas e middleware
 *   3. Os dados persistem apenas durante o runtime do processo
 *
 * Em produção, substituiríamos este módulo por um serviço que usa MongoDB, PostgreSQL, etc.
 */

/**
 * Array principal que armazena todos os livros.
 * Cada elemento é um objeto com a estrutura definida abaixo.
 *
 * Estrutura de cada livro:
 * {
 *   id: number,          // ID numérico auto-incrementado
 *   title: string,       // Título do livro (obrigatório)
 *   author: string,      // Autor (obrigatório)
 *   year: number,        // Ano de publicação (obrigatório)
 *   genre: string,       // Gênero literário (opcional)
 *   isbn: string,        // ISBN (opcional)
 *   createdAt: string,   // Timestamp ISO da criação
 *   updatedAt: string    // Timestamp ISO da última atualização
 * }
 */
const books = [];

/**
 * Contador para geração de IDs auto-incrementados.
 * Começa em 1 e incrementa a cada novo livro criado.
 * Usamos uma variável module-scoped (não exportada) para evitar manipulação externa.
 */
let nextId = 1;

/**
 * Seed inicial com dados de exemplo.
 * Isso permite testar a API imediatamente após iniciar o servidor,
 * sem precisar criar livros manualmente via POST.
 */
books.push(
  {
    id: 1,
    title: "Dom Casmurro",
    author: "Machado de Assis",
    year: 1899,
    genre: "Romance",
    isbn: "978-85-325-0870-6",
    createdAt: "2024-01-01T00:00:00.000Z",
    updatedAt: "2024-01-01T00:00:00.000Z",
  },
  {
    id: 2,
    title: "Memórias Póstumas de Brás Cubas",
    author: "Machado de Assis",
    year: 1881,
    genre: "Romance",
    isbn: "978-85-325-0869-0",
    createdAt: "2024-01-01T00:00:00.000Z",
    updatedAt: "2024-01-01T00:00:00.000Z",
  },
  {
    id: 3,
    title: "O Cortiço",
    author: "Aluísio Azevedo",
    year: 1890,
    genre: "Romance Naturalista",
    isbn: "978-85-325-0456-2",
    createdAt: "2024-01-01T00:00:00.000Z",
    updatedAt: "2024-01-01T00:00:00.000Z",
  }
);

// Atualiza o nextId para continuar após os dados seed
nextId = books.length + 1;

/**
 * ============================================================================
 * OPERAÇÕES CRUD SOBRE O ARRAY
 * ============================================================================
 */

/**
 * Cria um novo livro no array.
 * Gera ID auto-incrementado e timestamps de criação/atualização.
 *
 * @param {Object} bookData - Dados do livro a ser criado
 * @param {string} bookData.title - Título (obrigatório)
 * @param {string} bookData.author - Autor (obrigatório)
 * @param {number} bookData.year - Ano de publicação (obrigatório)
 * @param {string} [bookData.genre] - Gênero literário
 * @param {string} [bookData.isbn] - ISBN
 * @returns {Object} O livro criado com id, createdAt e updatedAt preenchidos
 */
function createBook(bookData) {
  const now = new Date().toISOString();
  const book = {
    id: nextId++, // Incrementa e atribui o ID atual
    ...bookData, // Espalha os dados fornecidos
    createdAt: now,
    updatedAt: now,
  };
  books.push(book); // Adiciona ao final do array
  return book;
}

/**
 * Busca um livro pelo seu ID numérico.
 * Usa find() que retorna o primeiro elemento que satisfaz a condição, ou undefined.
 *
 * @param {number} id - ID do livro a buscar
 * @returns {Object|undefined} O livro encontrado ou undefined se não existir
 */
function findBookById(id) {
  return books.find((book) => book.id === id);
}

/**
 * Busca todos os livros, opcionalmente aplicando filtros.
 *
 * @param {Object} [filters] - Filtros opcionais
 * @param {string} [filters.author] - Filtrar por autor (case-insensitive)
 * @param {string} [filters.genre] - Filtrar por gênero (case-insensitive)
 * @param {number} [filters.minYear] - Ano mínimo de publicação
 * @param {number} [filters.maxYear] - Ano máximo de publicação
 * @returns {Object[]} Array de livros que satisfazem os filtros
 */
function findAllBooks(filters = {}) {
  let result = [...books]; // Cria cópia para não mutar o array original

  // Aplica cada filtro apenas se for fornecido
  if (filters.author) {
    const authorLower = filters.author.toLowerCase();
    result = result.filter((book) => book.author.toLowerCase().includes(authorLower));
  }

  if (filters.genre) {
    const genreLower = filters.genre.toLowerCase();
    result = result.filter((book) => book.genre?.toLowerCase().includes(genreLower));
  }

  if (filters.minYear) {
    result = result.filter((book) => book.year >= filters.minYear);
  }

  if (filters.maxYear) {
    result = result.filter((book) => book.year <= filters.maxYear);
  }

  return result;
}

/**
 * Atualiza um livro existente pelo ID.
 * Se o livro não existir, retorna undefined.
 * Atualiza o timestamp updatedAt automaticamente.
 *
 * @param {number} id - ID do livro a atualizar
 * @param {Object} updates - Campos a atualizar (parcial)
 * @returns {Object|undefined} O livro atualizado ou undefined se não encontrado
 */
function updateBook(id, updates) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return undefined;

  // Atualiza apenas os campos fornecidos (partial update)
  books[index] = {
    ...books[index], // Mantém todos os campos existentes
    ...updates,      // Sobrescreve com os novos valores
    updatedAt: new Date().toISOString(), // Sempre atualiza o timestamp
  };

  return books[index];
}

/**
 * Remove um livro do array pelo ID.
 * Usa splice para remover o elemento na posição encontrada (O(n) para busca + O(1) para remoção).
 *
 * @param {number} id - ID do livro a remover
 * @returns {boolean} true se removido, false se não encontrado
 */
function deleteBook(id) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return false;

  books.splice(index, 1); // Remove 1 elemento na posição index
  return true;
}

/**
 * Retorna estatísticas básicas sobre o acervo de livros.
 * Usado pelo endpoint GET /stats.
 *
 * @returns {Object} Estatísticas do acervo
 */
function getStats() {
  const total = books.length;

  // Agrupamento por autor: conta quantos livros cada autor tem
  const byAuthor = books.reduce((acc, book) => {
    acc[book.author] = (acc[book.author] || 0) + 1;
    return acc;
  }, {});

  // Agrupamento por gênero
  const byGenre = books.reduce((acc, book) => {
    if (book.genre) {
      acc[book.genre] = (acc[book.genre] || 0) + 1;
    }
    return acc;
  }, {});

  // Ano mais recente e mais antigo
  const years = books.map((b) => b.year);
  const minYear = years.length ? Math.min(...years) : null;
  const maxYear = years.length ? Math.max(...years) : null;

  return {
    total,
    byAuthor,
    byGenre,
    minYear,
    maxYear,
  };
}

/**
 * ============================================================================
 * EXPORTAÇÃO — Padrão named exports para acoplamento baixo
 * ============================================================================
 */
module.exports = {
  books,         // Exportamos o array para casos onde acesso direto é necessário
  nextId,        // Exportamos para testes (não recomendado em produção)
  createBook,
  findBookById,
  findAllBooks,
  updateBook,
  deleteBook,
  getStats,
};
```

**Explicação:** Escolhemos um **array** como estrutura de dados principal porque ele oferece métodos integrados poderosos (`filter`, `find`, `findIndex`, `splice`) e mantém a ordem de inserção. Para este exemplo educacional, não usamos banco de dados para manter o foco nos conceitos REST. O objeto é exportado junto com as funções CRUD — em produção, esse módulo seria substituído por um repositório que usa MongoDB ou PostgreSQL. Os dados seed permitem testar imediatamente sem precisar criar registros manualmente.

