## Arquivo 5: `src/routes/books.js` — Rotas da API

```javascript
/**
 * ============================================================================
 * ROTAS DA API DE LIVROS
 * ============================================================================
 *
 * POR QUE organizar rotas em arquivo separado?
 * --------------------------------------------
 * Separar rotas do app principal (app.js) segue o princípio de responsabilidade única:
 *   - app.js configura middleware global e rotas de sistema
 *   - routes/books.js gerencia exclusivamente as operações CRUD de livros
 * Isso facilita a manutenção, testes unitários e escalabilidade (podemos ter
 * múltiplos arquivos de rota para diferentes recursos).
 *
 * Convenções REST utilizadas:
 * ----------------------------
 *   GET    /books          → Lista todos os livros (com filtragem opcional)
 *   GET    /books/:id      → Busca um livro pelo ID
 *   POST   /books          → Cria um novo livro
 *   PUT    /books/:id      → Atualiza completamente um livro (full update)
 *   DELETE /books/:id      → Remove um livro
 *   GET    /stats          → Estatísticas do acervo
 *
 * Cada rota segue o padrão:
 *   1. Validar entrada (parâmetros, corpo da requisição)
 *   2. Executar operação no modelo de dados
 *   3. Retornar resposta com código HTTP apropriado
 *   4. Tratar erros via asyncHandler + middleware errorHandler
 */

const express = require("express");
const router = express.Router(); // Cria um roteador independente

// Importa funções do módulo de dados (camada de persistência)
const {
  createBook,
  findBookById,
  findAllBooks,
  updateBook,
  deleteBook,
  getStats,
} = require("../data/books");

// Importa classes de erro e handler assíncrono
const { ValidationError, NotFoundError } = require("../classes/errors");
const { asyncHandler } = require("../middleware/errorHandler");

/**
 * ============================================================================
 * GET /books — Listar todos os livros com filtragem
 * ============================================================================
 *
 * Parâmetros de query (opcionais):
 *   ?author=Machado    → Filtra por autor (busca parcial, case-insensitive)
 *   ?genre=Romance     → Filtra por gênero
 *   ?minYear=1800      → Ano mínimo de publicação
 *   ?maxYear=1900      → Ano máximo de publicação
 *
 * Exemplos de uso:
 *   curl http://localhost:3000/books
 *   curl "http://localhost:3000/books?author=Machado"
 *   curl "http://localhost:3000/books?genre=Romance&minYear=1850"
 *
 * Código HTTP de resposta: 200 OK
 */
router.get(
  "/books",
  asyncHandler(async (req, res) => {
    // Extrai parâmetros de query da URL; valores ausentes são undefined
    const { author, genre, minYear, maxYear } = req.query;

    // Constrói o objeto de filtros apenas com campos presentes
    // Isso evita que filtros vazios interfiram na consulta
    const filters = {};
    if (author) filters.author = author;
    if (genre) filters.genre = genre;
    if (minYear) filters.minYear = parseInt(minYear, 10);
    if (maxYear) filters.maxYear = parseInt(maxYear, 10);

    // Busca livros aplicando os filtros
    const result = findAllBooks(filters);

    // Resposta 200 com lista de livros
    // Usamos { success: true } para consistência com a estrutura de erro
    res.status(200).json({
      success: true,
      count: result.length, // Número de livros retornados (útil para paginação futura)
      data: result,
    });
  })
);

/**
 * ============================================================================
 * GET /books/:id — Obter único livro por ID
 * ============================================================================
 *
 * Parâmetros de rota:
 *   :id → ID numérico do livro
 *
 * Exemplos de uso:
 *   curl http://localhost:3000/books/1
 *   curl http://localhost:3000/books/999  → 404 Not Found
 *
 * Código HTTP de resposta: 200 OK | 404 Not Found
 */
router.get(
  "/books/:id",
  asyncHandler(async (req, res) => {
    // Converte ID de string (vem da URL como string) para número
    const id = parseInt(req.params.id, 10);

    // Valida se o ID é um número válido
    if (isNaN(id)) {
      throw new ValidationError("ID inválido. Deve ser um número inteiro.", {
        field: "id",
        value: req.params.id,
      });
    }

    // Busca o livro no armazenamento
    const book = findBookById(id);

    // Se não encontrado, lança NotFoundError (capturado pelo middleware de erro)
    if (!book) {
      throw new NotFoundError("Book", id);
    }

    // Resposta 200 com dados do livro
    res.status(200).json({
      success: true,
      data: book,
    });
  })
);

/**
 * ============================================================================
 * POST /books — Criar novo livro
 * ============================================================================
 *
 * Corpo da requisição (JSON):
 *   {
 *     "title": "Dom Casmurro",       // obrigatório
 *     "author": "Machado de Assis",  // obrigatório
 *     "year": 1899,                  // obrigatório, número
 *     "genre": "Romance",            // opcional
 *     "isbn": "978-85-325-0870-6"    // opcional
 *   }
 *
 * Exemplos de uso:
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"Quincas Borba","author":"Machado de Assis","year":1891}'
 *
 *   # Postman: POST http://localhost:3000/books
 *   # Body (raw JSON): {"title":"...","author":"...","year":...}
 *
 * Código HTTP de resposta: 201 Created | 400 Bad Request
 */
router.post(
  "/books",
  asyncHandler(async (req, res) => {
    // Extrai dados do corpo da requisição
    const { title, author, year, genre, isbn } = req.body;

    // Validação: campos obrigatórios
    if (!title || !author || year === undefined || year === null) {
      throw new ValidationError("Campos obrigatórios ausentes.", {
        missing: ["title", "author", "year"].filter((field) => {
          if (field === "year") return year === undefined || year === null;
          return !req.body[field];
        }),
      });
    }

    // Validação: ano deve ser um número válido e razoável
    const yearNum = parseInt(year, 10);
    if (isNaN(yearNum) || yearNum < 0 || yearNum > new Date().getFullYear() + 1) {
      throw new ValidationError("Ano de publicação inválido. Deve ser um número entre 0 e o ano atual + 1.", {
        field: "year",
        value: year,
      });
    }

    // Cria o livro no armazenamento
    const book = createBook({
      title,
      author,
      year: yearNum,
      genre: genre || null,
      isbn: isbn || null,
    });

    // Resposta 201 Created — indica que um novo recurso foi criado com sucesso
    // O corpo inclui o livro completo criado
    res.status(201).json({
      success: true,
      message: "Livro criado com sucesso.",
      data: book,
    });
  })
);

/**
 * ============================================================================
 * PUT /books/:id — Atualizar livro existente (Full Update)
 * ============================================================================
 *
 * Diferença entre PUT e PATCH:
 *   - PUT = substituição completa do recurso (todos os campos obrigatórios devem ser enviados)
 *   - PATCH = atualização parcial (apenas os campos que interessam)
 *
 * Escolhemos PUT aqui porque é mais simples de validar e entender.
 * Em uma API real, poderíamos oferecer ambos os métodos.
 *
 * Corpo da requisição:
 *   {
 *     "title": "Novo Título",
 *     "author": "Novo Autor",
 *     "year": 2000,
 *     "genre": "Ficção",
 *     "isbn": "978-..."
 *   }
 *
 * Exemplos de uso:
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"Dom Casmurro (Ed. Crítica)","author":"Machado de Assis","year":1899}'
 *
 * Código HTTP de resposta: 200 OK | 400 Bad Request | 404 Not Found
 */
router.put(
  "/books/:id",
  asyncHandler(async (req, res) => {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      throw new ValidationError("ID inválido. Deve ser um número inteiro.", {
        field: "id",
        value: req.params.id,
      });
    }

    // Busca o livro existente para verificar se existe
    const existingBook = findBookById(id);
    if (!existingBook) {
      throw new NotFoundError("Book", id);
    }

    // Validação dos campos obrigatórios no corpo
    const { title, author, year, genre, isbn } = req.body;

    if (!title || !author || year === undefined || year === null) {
      throw new ValidationError("Campos obrigatórios ausentes. Para PUT, todos os campos devem ser fornecidos.", {
        missing: ["title", "author", "year"].filter((field) => {
          if (field === "year") return year === undefined || year === null;
          return !req.body[field];
        }),
      });
    }

    const yearNum = parseInt(year, 10);
    if (isNaN(yearNum) || yearNum < 0 || yearNum > new Date().getFullYear() + 1) {
      throw new ValidationError("Ano de publicação inválido.", { field: "year", value: year });
    }

    // Atualiza o livro com todos os campos fornecidos
    const updatedBook = updateBook(id, {
      title,
      author,
      year: yearNum,
      genre: genre || null,
      isbn: isbn || null,
    });

    res.status(200).json({
      success: true,
      message: "Livro atualizado com sucesso.",
      data: updatedBook,
    });
  })
);

/**
 * ============================================================================
 * DELETE /books/:id — Excluir livro
 * ============================================================================
 *
 * Exemplos de uso:
 *   curl -X DELETE http://localhost:3000/books/1
 *   curl -X DELETE http://localhost:3000/books/999  → 404 Not Found
 *
 * Código HTTP de resposta: 200 OK | 404 Not Found
 */
router.delete(
  "/books/:id",
  asyncHandler(async (req, res) => {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      throw new ValidationError("ID inválido. Deve ser um número inteiro.", {
        field: "id",
        value: req.params.id,
      });
    }

    // Verifica se o livro existe antes de tentar deletar
    const existingBook = findBookById(id);
    if (!existingBook) {
      throw new NotFoundError("Book", id);
    }

    // Remove o livro do armazenamento
    const deleted = deleteBook(id);

    // Resposta 200 com confirmação (poderíamos usar 204 No Content para não retornar body)
    res.status(200).json({
      success: true,
      message: `Livro '${existingBook.title}' excluído com sucesso.`,
      data: { id: existingBook.id, title: existingBook.title },
    });
  })
);

/**
 * ============================================================================
 * GET /stats — Retornar estatísticas do acervo
 * ============================================================================
 *
 * Retorna métricas agregadas sobre os livros armazenados:
 *   - total: número total de livros
 *   - byAuthor: contagem de livros por autor
 *   - byGenre: contagem de livros por gênero
 *   - minYear / maxYear: intervalo de anos coberto
 *
 * Exemplos de uso:
 *   curl http://localhost:3000/stats
 *
 * Código HTTP de resposta: 200 OK
 */
router.get(
  "/stats",
  asyncHandler(async (req, res) => {
    const stats = getStats();

    res.status(200).json({
      success: true,
      data: stats,
    });
  })
);

/**
 * ============================================================================
 * EXPORTAÇÃO DO ROTEADOR
 * ============================================================================
 * O roteador é importado em app.js e montado com prefixo /api
 */
module.exports = router;
```

**Explicação:** Cada rota segue o padrão REST de forma consistente: métodos HTTP apropriados, códigos de status corretos (200, 201, 400, 404), e estrutura de resposta padronizada com `{ success, data/error }`. A validação é feita **antes** de executar a operação — um princípio de "fail fast" que evita processamento desnecessário. O `asyncHandler` garante que erros lançados dentro dos handlers sejam capturados e encaminados ao middleware de erro centralizado. Note a diferença entre PUT (substituição completa) e a abordagem educacional: em produção, poderíamos oferecer PATCH para atualizações parciais.

