## File 2: `src/models/bookStore.js` — In-Memory Data Layer

```javascript
/**
 * ============================================================================
 * FILE: src/models/bookStore.js
 * DESCRIPTION: In-memory data store for books.
 *
 * DESIGN RATIONALE:
 *   We use a plain JavaScript array of objects to simulate a database.
 *   - Arrays are ordered, which is useful if we ever want to preserve insertion order.
 *   - Each book gets a numeric ID that auto-increments, mimicking an AUTO_INCREMENT
 *     column in SQL or ObjectId generation in MongoDB.
 *   - In production, you would replace this entire file with calls to a real DB
 *     (e.g., pg.query(), mongoose.model.find()). The route handlers below do NOT
 *     need to change — that's the power of abstraction.
 * ============================================================================
 */

// --------------------------------------------------------------------------
// DATA STRUCTURE: Array of book objects
// Each book has: { id, title, author, genre, publishedYear, createdAt }
// We store `createdAt` so we can sort or filter by creation time later.
// --------------------------------------------------------------------------

/** @type {Array<{id: number, title: string, author: string, genre: string, publishedYear: number, createdAt: string}>} */
const books = [];

/**
 * The next ID to assign. Starts at 1 and increments with each new book.
 * Using a closure-like pattern (module-level variable) keeps state encapsulated
 * within this module — route handlers import functions, not the raw array.
 */
let nextId = 1;

// --------------------------------------------------------------------------
// CRUD OPERATIONS
// Each function is pure with respect to the `books` array (they mutate it),
// but they are synchronous because in-memory operations are instant.
// If we were using a real DB, these would be async and return Promises.
// --------------------------------------------------------------------------

/**
 * Retrieves every book currently stored.
 * @returns {Array<{id: number, title: string, author: string, genre: string, publishedYear: number, createdAt: string}>}
 */
function getAllBooks() {
  // Return a shallow copy so callers cannot accidentally mutate the internal array.
  return [...books];
}

/**
 * Finds a single book by its numeric ID.
 * @param {number} id - The unique identifier of the book.
 * @returns {{id: number, title: string, author: string, genre: string, publishedYear: number, createdAt: string}|null}
 *   Returns null if no book with that ID exists.
 */
function getBookById(id) {
  // Array.prototype.find returns the first matching element or undefined.
  return books.find((book) => book.id === id) || null;
}

/**
 * Creates a new book and appends it to the store.
 * @param {{title: string, author: string, genre: string, publishedYear: number}} data
 *   The partial book object provided by the client (id and createdAt are auto-generated).
 * @returns {{id: number, title: string, author: string, genre: string, publishedYear: number, createdAt: string}}
 *   The newly created book with its assigned ID and timestamp.
 */
function createBook(data) {
  const newBook = {
    id: nextId++, // Assign current ID then increment for the next call.
    title: data.title,
    author: data.author,
    genre: data.genre,
    publishedYear: data.publishedYear,
    createdAt: new Date().toISOString(), // ISO 8601 format is the standard for APIs.
  };

  books.push(newBook);
  return newBook;
}

/**
 * Replaces an existing book entirely with new data.
 * @param {number} id - The ID of the book to update.
 * @param {{title: string, author: string, genre: string, publishedYear: number}} data
 *   The complete replacement data (all fields must be present).
 * @returns {{id: number, title: string, author: string, genre: string, publishedYear: number, createdAt: string}|null}
 *   The updated book, or null if no book with that ID was found.
 */
function updateBook(id, data) {
  const index = books.findIndex((book) => book.id === id);

  if (index === -1) {
    return null; // Book not found — caller should handle this as a 404.
  }

  // Replace the entire object to enforce full-update semantics (PUT vs PATCH).
  const updatedBook = {
    id: books[index].id,       // ID never changes.
    title: data.title,
    author: data.author,
    genre: data.genre,
    publishedYear: data.publishedYear,
    createdAt: books[index].createdAt, // Preserve the original creation timestamp.
  };

  books[index] = updatedBook;
  return updatedBook;
}

/**
 * Removes a book from the store by its ID.
 * @param {number} id - The unique identifier of the book to delete.
 * @returns {boolean} True if the book was found and deleted, false otherwise.
 */
function deleteBook(id) {
  const index = books.findIndex((book) => book.id === id);

  if (index === -1) {
    return false; // Book not found — caller should handle this as a 404.
  }

  // splice removes the element at `index` and shifts subsequent elements down.
  books.splice(index, 1);
  return true;
}

/**
 * Computes aggregate statistics about the book collection.
 * @returns {{totalBooks: number, averagePublishedYear: number, genres: Record<string, number>, authors: Record<string, number>}}
 */
function getStats() {
  const totalBooks = books.length;

  // Compute the average published year (rounded to 2 decimal places).
  const averagePublishedYear =
    totalBooks > 0
      ? Math.round((books.reduce((sum, b) => sum + b.publishedYear, 0) / totalBooks) * 100) / 100
      : 0;

  // Count how many books exist per genre.
  const genres = {};
  for (const book of books) {
    genres[book.genre] = (genres[book.genre] || 0) + 1;
  }

  // Count how many books exist per author.
  const authors = {};
  for (const book of books) {
    authors[book.author] = (authors[book.author] || 0) + 1;
  }

  return { totalBooks, averagePublishedYear, genres, authors };
}

// --------------------------------------------------------------------------
// EXPORTS: We use CommonJS (module.exports) because it's the default in Node.js.
// ES modules (import/export) are also valid but require "type": "module" in
// package.json and can cause issues with some tooling. For this educational
// example, CommonJS keeps things simple and universally compatible.
// --------------------------------------------------------------------------
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
};
```

