## File 3: `src/middleware/errorHandler.js` — Custom Error Classes & Middleware

```javascript
/**
 * ============================================================================
 * FILE: src/middleware/errorHandler.js
 * DESCRIPTION: Custom error classes and a centralized Express error-handling
 *              middleware.
 *
 * WHY CUSTOM ERROR CLASSES?
 *   JavaScript's built-in Error class is generic. By creating subclasses like
 *   NotFoundError and ValidationError, we can:
 *     1. Distinguish between different failure modes in our middleware.
 *     2. Attach extra metadata (e.g., the missing field name).
 *     3. Return appropriate HTTP status codes automatically.
 *
 * WHY CENTRALIZED ERROR MIDDLEWARE?
 *   Express supports a special 4-argument middleware function:
 *     (err, req, res, next) => { ... }
 *   When ANY route handler calls `next(err)` or throws an error, Express skips
 *   all remaining normal middleware and jumps straight to this handler. This
 *   means we never have to repeat error-response logic in every route — we write
 *   it once here. Without this pattern, a single forgotten error check could
 *   leave the client hanging with no response.
 * ============================================================================
 */

// --------------------------------------------------------------------------
// CUSTOM ERROR CLASSES
// Each extends Error and sets a default HTTP status code via `this.statusCode`.
// We override the constructor to ensure `message` is set correctly even when
// the error is caught by V8's internal error handling (which can lose `this`).
// --------------------------------------------------------------------------

/**
 * Base class for all API errors. Provides a consistent shape: { type, message, statusCode }.
 */
class ApiError extends Error {
  /**
   * @param {string} message - Human-readable description of the error.
   * @param {number} statusCode - HTTP status code (default: 500 Internal Server Error).
   */
  constructor(message, statusCode = 500) {
    super(message);
    this.statusCode = statusCode;
    this.type = 'ApiError';
  }
}

/**
 * Thrown when a requested resource does not exist (HTTP 404).
 * Example: GET /books/999 when only books 1–5 exist.
 */
class NotFoundError extends ApiError {
  constructor(message = 'Resource not found') {
    super(message, 404);
    this.type = 'NotFoundError';
  }
}

/**
 * Thrown when client input fails validation (HTTP 400).
 * Example: POST /books with a missing `title` field.
 */
class ValidationError extends ApiError {
  /**
   * @param {string} message - Description of the validation failure.
   * @param {Array<{field: string, message: string}>} [details] - Optional array of per-field errors.
   */
  constructor(message, details = []) {
    super(message, 400);
    this.type = 'ValidationError';
    this.details = details;
  }
}

// --------------------------------------------------------------------------
// VALIDATION HELPER
 * This function is used by route handlers to validate incoming request bodies.
 * It throws a ValidationError with per-field details so the error middleware
 * can return a structured JSON response.
 * --------------------------------------------------------------------------

/**
 * Validates that all required fields are present and have valid types/values.
 * @param {Object} body - The parsed request body (usually from express.json()).
 * @param {Array<{field: string, required: boolean, type?: string}>} rules
 *   Each rule specifies a field name, whether it's required, and its expected type.
 * @throws {ValidationError} If any validation rule fails.
 */
function validateRequestBody(body, rules) {
  const missingFields = [];

  for (const rule of rules) {
    const value = body[rule.field];

    // Check if a required field is missing or undefined/null.
    if (rule.required && (value === undefined || value === null)) {
      missingFields.push({
        field: rule.field,
        message: `${rule.field} is required`,
      });
      continue;
    }

    // If the field exists, check its type.
    if (value !== undefined && value !== null) {
      if (rule.type === 'number' && typeof value !== 'number') {
        missingFields.push({
          field: rule.field,
          message: `${rule.field} must be a number`,
        });
      } else if (rule.type === 'string' && typeof value !== 'string') {
        missingFields.push({
          field: rule.field,
          message: `${rule.field} must be a string`,
        });
      }
    }
  }

  // If any rules failed, throw a single ValidationError with all details.
  if (missingFields.length > 0) {
    throw new ValidationError(
      `${missingFields.length} validation error(s) found`,
      missingFields
    );
  }
}

// --------------------------------------------------------------------------
// EXPRESS ERROR-HANDLING MIDDLEWARE
 * This is the "catch-all" for any error that bubbles up through Express.
 * It MUST have exactly 4 parameters (err, req, res, next) — if you omit `next`,
 * Express treats it as a normal middleware and won't route errors to it.
 * --------------------------------------------------------------------------

/**
 * Centralized error handler. Responds with a consistent JSON shape regardless
 * of which error occurred. This is what the client sees when something goes wrong.
 *
 * @param {Error} err - The error object (instance of ApiError or any Error).
 * @param {import('express').Request} req - The Express request object.
 * @param {import('express').Response} res - The Express response object.
 * @param {import('express').NextFunction} next - Unused but required by Express signature.
 */
function errorHandler(err, req, res, next) {
  // Determine the status code: use err.statusCode if set, otherwise default to 500.
  const statusCode = err.statusCode || 500;

  // Build a consistent JSON response shape.
  /** @type {{status: string, message: string, details?: Array<{field: string, message: string}>}} */
  const responseBody = {
    status: 'error',
    message: err.message,
  };

  // If the error has per-field validation details, include them.
  if (err.details && err.details.length > 0) {
    responseBody.details = err.details;
  }

  // Log the full error stack to the server console for debugging.
  // In production, you'd send this to a logging service (e.g., Winston, Datadog).
  console.error(`[ERROR] ${statusCode} — ${err.message}`);
  if (process.env.NODE_ENV !== 'production') {
    console.error(err.stack);
  }

  // Send the JSON response.
  res.status(statusCode).json(responseBody);
}

// --------------------------------------------------------------------------
// EXPORTS
// --------------------------------------------------------------------------
module.exports = {
  ApiError,
  NotFoundError,
  ValidationError,
  validateRequestBody,
  errorHandler,
};
```

