## File 4: `src/routes/books.js` — Book Route Handlers

```javascript
/**
 * ============================================================================
 * FILE: src/routes/books.js
 * DESCRIPTION: Express route handlers for the /books resource.
 *
 * REST CONVENTIONS FOLLOWED:
 *   GET    /books          → List all books (with optional query filters)
 *   GET    /books/:id      → Get a single book by ID
 *   POST   /books          → Create a new book
 *   PUT    /books/:id      → Fully update an existing book
 *   DELETE /books/:id      → Delete a book
 *
 * WHY SEPARATE ROUTE FILE?
 *   As the API grows, keeping all routes in app.js becomes unmaintainable.
 *   By organizing routes into their own module, we can:
 *     - Test route logic independently.
 *     - Add new resources (e.g., /authors) without touching book routes.
 *     - Share middleware between related routes if needed.
 *
 * WHY ASYNC/AWAIT?
 *   Even though our data layer is synchronous today, we write handlers as
 *   async functions so that:
 *     1. They're ready for a future database swap (which will be async).
 *     2. We can use try/catch cleanly instead of .catch() chains.
 *     3. Express supports async route handlers natively — errors are caught
 *        and forwarded to our errorHandler middleware automatically.
 * ============================================================================
 */

const express = require('express');
const router = express.Router(); // Creates a standalone router instance.

// Import the data layer (in-memory store).
const { getAllBooks, getBookById, createBook, updateBook, deleteBook, getStats } = require('../models/bookStore');

// Import custom errors and validation helper.
const { NotFoundError, ValidationError, validateRequestBody } = require('../middleware/errorHandler');

// --------------------------------------------------------------------------
// VALIDATION RULES
 * These rules are reused across POST and PUT handlers to avoid duplication.
 * Each rule specifies: field name, whether it's required, and expected type.
 * --------------------------------------------------------------------------

/** Rules for creating a new book (all fields required). */
const CREATE_RULES = [
  { field: 'title',    required: true,  type: 'string' },
  { field: 'author',   required: true,  type: 'string' },
  { field: 'genre',    required: true,  type: 'string' },
  { field: 'publishedYear', required: true, type: 'number' },
];

/** Rules for updating a book (all fields required — PUT is a full replacement). */
const UPDATE_RULES = [
  { field: 'title',    required: true,  type: 'string' },
  { field: 'author',   required: true,  type: 'string' },
  { field: 'genre',    required: true,  type: 'string' },
  { field: 'publishedYear', required: true, type: 'number' },
];

// --------------------------------------------------------------------------
// GET /books — List all books with optional filtering
 *
 * Query parameters (all optional):
 *   - genre     : Filter by genre (e.g., ?genre=fiction)
 *   - author    : Filter by author name (case-insensitive partial match)
 *   - minYear   : Minimum published year (e.g., ?minYear=2000)
 *   - maxYear   : Maximum published year (e.g., ?maxYear=2024)
 *
 * Example: GET /books?genre=fiction&minYear=2000
 * --------------------------------------------------------------------------

/**
 * @name GET /books
 * @description Returns a JSON array of all books, optionally filtered by query params.
 * @param {import('express').Request} req - Express request with query parameters.
 * @param {import('express').Response} res - Express response object.
 */
router.get('/books', async (req, res) => {
  // Start with the full list of books.
  let result = getAllBooks();

  // Filter by genre if provided (exact match).
  if (req.query.genre) {
    result = result.filter((book) => book.genre.toLowerCase() === req.query.genre.toLowerCase());
  }

  // Filter by author if provided (case-insensitive partial match for flexibility).
  if (req.query.author) {
    const authorQuery = req.query.author.toLowerCase();
    result = result.filter((book) => book.author.toLowerCase().includes(authorQuery));
  }

  // Filter by minimum published year if provided.
  if (req.query.minYear) {
    const minYear = parseInt(req.query.minYear, 10);
    result = result.filter((book) => book.publishedYear >= minYear);
  }

  // Filter by maximum published year if provided.
  if (req.query.maxYear) {
    const maxYear = parseInt(req.query.maxYear, 10);
    result = result.filter((book) => book.publishedYear <= maxYear);
  }

  // Send the (possibly filtered) array as JSON with status 200 OK.
  res.json({
    count: result.length,
    data: result,
  });
});

// --------------------------------------------------------------------------
// GET /books/stats — Return aggregate statistics
 *
 * This is a custom endpoint that doesn't map to a single resource. It's common
 * in REST APIs to have "sub-resource" endpoints like this for analytics.
 * --------------------------------------------------------------------------

/**
 * @name GET /books/stats
 * @description Returns aggregate statistics about the book collection.
 * @param {import('express').Request} req - Express request object.
 * @param {import('express').Response} res - Express response object.
 */
router.get('/books/stats', async (req, res) => {
  const stats = getStats();
  res.json({
    status: 'success',
    data: stats,
  });
});

// --------------------------------------------------------------------------
// GET /books/:id — Get a single book by ID
 *
 * The :id segment is a route parameter. Express parses it and makes it
 * available as req.params.id (as a string). We convert it to a number
 * because our IDs are numeric.
 * --------------------------------------------------------------------------

/**
 * @name GET /books/:id
 * @description Returns a single book by its ID, or 404 if not found.
 * @param {import('express').Request} req - Express request with params.id.
 * @param {import('express').Response} res - Express response object.
 * @param {import('express').NextFunction} next - Express next middleware function.
 */
router.get('/books/:id', async (req, res, next) => {
  // Convert the string ID to a number. parseInt with radix 10 is explicit and safe.
  const id = parseInt(req.params.id, 10);

  // If parsing fails (e.g., /books/abc), the result is NaN.
  if (isNaN(id)) {
    // Instead of returning a 400 here, we let it fall through to getBookById,
    // which will return null, and then we throw NotFoundError for consistency.
    // This keeps the error handling centralized in one place.
  }

  const book = getBookById(id);

  if (!book) {
    // Throw NotFoundError instead of manually calling next() with a string.
    // Throwing an Error instance is cleaner and works seamlessly with our
    // errorHandler middleware (which checks err.statusCode).
    throw new NotFoundError(`Book with id ${id} not found`);
  }

  res.json({
    status: 'success',
    data: book,
  });
});

// --------------------------------------------------------------------------
// POST /books — Create a new book
 *
 * The request body must be JSON. Express's built-in express.json() middleware
 * (configured in app.js) parses it and makes it available as req.body.
 * We validate the body BEFORE attempting to create the book, so we never
 * store invalid data.
 * --------------------------------------------------------------------------

/**
 * @name POST /books
 * @description Creates a new book from the request body JSON.
 * @param {import('express').Request} req - Express request with parsed JSON body.
 * @param {import('express').Response} res - Express response object.
 */
router.post('/books', async (req, res) => {
  // Validate that all required fields are present and have correct types.
  // If validation fails, validateRequestBody throws a ValidationError which is
  // caught by our errorHandler middleware and returned as a 400 JSON response.
  validateRequestBody(req.body, CREATE_RULES);

  const newBook = createBook(req.body);

  // 201 Created is the standard status for successful resource creation.
  // We also set the Location header so clients know where to find the new resource.
  res.status(201).json({
    status: 'created',
    data: newBook,
  });
});

// --------------------------------------------------------------------------
// PUT /books/:id — Fully update an existing book
 *
 * PUT semantics: the request body is the COMPLETE replacement for the resource.
 * This is different from PATCH, which would only update specified fields.
 * We enforce this by requiring ALL fields in the validation rules.
 * --------------------------------------------------------------------------

/**
 * @name PUT /books/:id
 * @description Fully replaces a book's data. Returns 404 if not found.
 * @param {import('express').Request} req - Express request with params.id and JSON body.
 * @param {import('express').Response} res - Express response object.
 */
router.put('/books/:id', async (req, res) => {
  const id = parseInt(req.params.id, 10);

  // Validate the incoming data before attempting any mutation.
  validateRequestBody(req.body, UPDATE_RULES);

  const updatedBook = updateBook(id, req.body);

  if (!updatedBook) {
    throw new NotFoundError(`Book with id ${id} not found`);
  }

  // 200 OK is standard for a successful PUT that returns the updated resource.
  res.json({
    status: 'updated',
    data: updatedBook,
  });
});

// --------------------------------------------------------------------------
// DELETE /books/:id — Delete a book
 *
 * REST convention: DELETE responses typically return either no body (204 No Content)
 * or a confirmation message. We return 200 with a confirmation for clarity in
 * this educational example. In production, 204 is more common.
 * --------------------------------------------------------------------------

/**
 * @name DELETE /books/:id
 * @description Deletes a book by ID. Returns 404 if not found.
 * @param {import('express').Request} req - Express request with params.id.
 * @param {import('express').Response} res - Express response object.
 */
router.delete('/books/:id', async (req, res) => {
  const id = parseInt(req.params.id, 10);

  const deleted = deleteBook(id);

  if (!deleted) {
    throw new NotFoundError(`Book with id ${id} not found`);
  }

  // 200 OK with a confirmation message. Alternatively, use res.status(204).send().
  res.json({
    status: 'deleted',
    message: `Book with id ${id} has been deleted`,
  });
});

// --------------------------------------------------------------------------
// EXPORTS
 * We export the router so app.js can mount it at the desired path.
 * This is the standard Express pattern for organizing routes.
 * --------------------------------------------------------------------------
module.exports = router;
```

