## File 5: `src/app.js` — Application Entry Point

```javascript
/**
 * ============================================================================
 * FILE: src/app.js
 * DESCRIPTION: Main application entry point. Configures Express middleware,
 *              mounts routes, and starts the HTTP server.
 *
 * MIDDLEWARE ORDER MATTERS IN EXPRESS:
 *   Express processes middleware in the order it's registered. The typical
 *   pattern is:
 *     1. Body-parsing middleware (express.json()) — parses incoming JSON bodies.
 *     2. Route handlers — handle requests and send responses.
 *     3. Error-handling middleware — catches errors from any preceding handler.
 *
 *   If you put the error handler BEFORE routes, it will never see route errors.
 *   If you put express.json() AFTER routes, req.body will be undefined.
 * ============================================================================
 */

const express = require('express');
const bookRoutes = require('./routes/books');
const { errorHandler } = require('./middleware/errorHandler');

// --------------------------------------------------------------------------
// APPLICATION SETUP
 * express() creates a new Express application instance. This is the core object
 * that holds our middleware, routes, and configuration.
 * --------------------------------------------------------------------------
const app = express();

// --------------------------------------------------------------------------
// MIDDLEWARE CONFIGURATION
 * --------------------------------------------------------------------------

/**
 * Built-in Express middleware that parses incoming JSON request bodies.
 * Makes the parsed data available as req.body.
 *
 * Without this, POST/PUT requests with JSON bodies would have req.body === undefined.
 * We set `limit: '10kb'` to prevent clients from sending extremely large payloads
 * that could exhaust server memory (a simple DoS prevention measure).
 */
app.use(express.json({ limit: '10kb' }));

/**
 * Simple logging middleware that prints each request to the console.
 * This is useful for debugging and monitoring during development.
 * In production, you'd replace this with a proper logger (Winston, Pino, etc.).
 */
app.use((req, res, next) => {
  // Log: [TIMESTAMP] METHOD PATH
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.url}`);
  next(); // Pass control to the next middleware/route handler.
});

// --------------------------------------------------------------------------
// ROUTE MOUNTING
 * We mount the book routes at the root path ('/'). This means all routes in
 * books.js will be prefixed with '/'. For example, router.get('/books') becomes
 * accessible at GET /books.
 *
 * You could also mount at a sub-path like '/api/v1' for versioning:
 *   app.use('/api/v1', bookRoutes);
 * --------------------------------------------------------------------------
app.use('/', bookRoutes);

// --------------------------------------------------------------------------
// 404 HANDLER FOR UNRECOGNIZED ROUTES
 * If a request reaches this point, no route matched. We return 404 manually
 * instead of letting it fall through to the error handler (which would return 500).
 * --------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: `Route ${req.method} ${req.url} not found`,
  });
});

// --------------------------------------------------------------------------
// CENTRALIZED ERROR HANDLER
 * This MUST be the last middleware registered. It catches errors thrown by any
 * route handler or middleware above it. Remember: it must have 4 parameters
 * (err, req, res, next) for Express to recognize it as error-handling middleware.
 * --------------------------------------------------------------------------
app.use(errorHandler);

// --------------------------------------------------------------------------
// SERVER STARTUP
 * --------------------------------------------------------------------------

/** The port the server will listen on. Defaults to 3000 if not set via environment variable. */
const PORT = process.env.PORT || 3000;

/**
 * Starts the HTTP server and logs a confirmation message.
 * We wrap in try/catch because server.listen() can throw (e.g., port already in use).
 */
app.listen(PORT, () => {
  console.log(`========================================`);
  console.log(`  Book REST API running on port ${PORT}`);
  console.log(`  Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`========================================`);
  console.log(`\nTest endpoints:`);
  console.log(`  GET  http://localhost:${PORT}/books`);
  console.log(`  POST http://localhost:${PORT}/books`);
  console.log(`  PUT  http://localhost:${PORT}/books/1`);
  console.log(`  DELETE http://localhost:${PORT}/books/1`);
  console.log(`  GET  http://localhost:${PORT}/books/stats`);
});
```

