## Arquivo 2: `src/models/book.js`

```javascript
/**
 * ============================================================
 * MODEL — Camada de Dados (Em Memória)
 * ============================================================
 *
 * POR QUE USAR UM ARRAY EM MEMÓRIA?
 * ---------------------------------
 * Para este exemplo educacional, optamos por um array em memória
 * ao invés de um banco de dados real. Isso permite:
 *   1. Focar nos conceitos de REST sem complexidade adicional.
 *   2. Executar a API com zero configuração externa.
 *   3. Entender o fluxo completo CRUD antes de adicionar persistência.
 *
 * ESTRUTURA DE DADOS ESCOLHIDA: Array de Objetos
 * ----------------------------------------------
 * Cada livro é um objeto com as seguintes propriedades:
 *   - id (number): Identificador único, incrementado automaticamente.
 *     Usamos number em vez de string/UUID porque IDs sequenciais são
 *     mais legíveis para depuração e o escopo do exemplo não exige
 *     distribuição ou colisão.
 *   - title (string): Título do livro — obrigatório.
 *   - author (string): Autor do livro — obrigatório.
 *   - year (number): Ano de publicação — opcional, mas recomendado.
 *   - genre (string): Gênero literário — opcional.
 *   - createdAt (string): Timestamp ISO 8601 da criação.
 *     Usamos ISO 8601 porque é o padrão da indústria para troca de datas
 *     em APIs JSON, evitando ambiguidades de fuso horário.
 *   - updatedAt (string): Timestamp ISO 8601 da última atualização.
 *
 * POR QUE NÃO USAR Map()?
 * -----------------------
 * Um Map seria tecnicamente mais eficiente para buscas por ID (O(1)),
 * mas um array é mais adequado aqui porque:
 *   - Suporta filtragem e ordenação nativas com métodos como filter(), sort().
 *   - É mais fácil de serializar para JSON.
 *   - A escala do exemplo não justifica a complexidade adicional.
 *
 * Em uma aplicação real, substituiríamos esta camada por um ORM ou
 * driver de banco de dados (MongoDB, PostgreSQL, etc.).
 */

// Estado global da aplicação — em memória, persiste durante o runtime do processo.
// Em produção, isso seria substituído por uma conexão a um banco de dados.
let books = [];

// Contador para gerar IDs únicos sequenciais.
// Inicializamos com 1 porque IDs começam em 1 para melhor legibilidade.
let nextId = 1;

/**
 * Classe personalizada de erro para validação de entrada.
 *
 * POR QUE CRIAR UMA CLASSE DE ERRO ESPECÍFICA?
 * --------------------------------------------
 * Erros de validação são diferentes de erros internos do servidor.
 * Ter uma classe dedicada permite:
 *   - Diferenciar status HTTP 400 (Bad Request) de 500 (Internal Server Error).
 *   - Incluir campos específicos no payload de erro (ex: quais campos falharam).
 *   - Facilitar o tratamento em middlewares centralizados.
 */
class ValidationError extends Error {
  /**
   * @param {string} message — Mensagem descritiva do erro.
   * @param {Array<{field: string, message: string}>} [details] — Detalhes por campo.
   */
  constructor(message, details = []) {
    super(message);
    this.name = 'ValidationError';
    this.statusCode = 400; // Bad Request — o cliente enviou dados inválidos.
    this.details = details;
  }
}

/**
 * Classe personalizada de erro para recursos não encontrados.
 *
 * Escolhemos separar NotFoundError de ValidationError porque:
 *   - NotFound indica que o recurso existe no domínio, mas não foi localizado.
 *   - A API pode retornar mensagens diferentes para cada caso.
 */
class NotFoundError extends Error {
  /**
   * @param {string} resource — Nome do recurso (ex: "Book").
   * @param {*} id — ID procurado.
   */
  constructor(resource = 'Resource', id) {
    super(`${resource} with id ${id} not found`);
    this.name = 'NotFoundError';
    this.statusCode = 404; // Not Found.
    this.resource = resource;
    this.id = id;
  }
}

// ============================================================
// FUNÇÕES DO MODEL — Operações CRUD sobre o array de livros
// ============================================================

/**
 * Retorna todos os livros armazenados.
 *
 * @returns {Array<Object>} Lista completa de livros.
 */
function getAllBooks() {
  return books;
}

/**
 * Busca um livro pelo seu ID numérico.
 *
 * POR QUE USAR Number(id) EM VEZ DE id DIRETOAMENTE?
 * --------------------------------------------------
 * Os parâmetros de rota do Express são sempre strings.
 * Converter explicitamente evita bugs de comparação estrita (===).
 * Por exemplo: 1 !== "1" em JavaScript.
 *
 * @param {number|string} id — ID do livro a ser buscado.
 * @returns {Object|null} O livro encontrado ou null se não existir.
 */
function getBookById(id) {
  return books.find(book => book.id === Number(id)) || null;
}

/**
 * Cria um novo livro no array e retorna o objeto criado.
 *
 * A função gera automaticamente:
 *   - Um ID único incrementando nextId.
 *   - Timestamps de criação e atualização em ISO 8601.
 *
 * @param {Object} bookData — Dados do livro a ser criado.
 * @param {string} bookData.title — Título (obrigatório).
 * @param {string} bookData.author — Autor (obrigatório).
 * @param {number} [bookData.year] — Ano de publicação (opcional).
 * @param {string} [bookData.genre] — Gênero (opcional).
 * @returns {Object} O livro criado com todos os campos preenchidos.
 * @throws {ValidationError} Se os campos obrigatórios estiverem ausentes.
 */
function createBook(bookData) {
  const newBook = {
    id: nextId++, // Incrementa e atribui o ID atual, depois incrementa para o próximo.
    title: bookData.title,
    author: bookData.author,
    year: bookData.year || null,
    genre: bookData.genre || null,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };

  books.push(newBook);
  return newBook;
}

/**
 * Atualiza um livro existente pelo ID.
 *
 * POR QUE RETORNAR O LIVRO ATUALIZADO E NÃO SOMENTE SUCESSO?
 * ----------------------------------------------------------
 * Convenção REST: respostas PUT devem retornar o recurso atualizado,
 * permitindo que o cliente sincronize seu estado sem fazer outra requisição GET.
 * Isso segue o padrão "Return Represent" da especificação HTTP/1.1.
 *
 * @param {number|string} id — ID do livro a atualizar.
 * @param {Object} updates — Campos a atualizar (parcial).
 * @returns {Object} O livro atualizado.
 * @throws {NotFoundError} Se o livro não for encontrado.
 */
function updateBook(id, updates) {
  const index = books.findIndex(book => book.id === Number(id));

  if (index === -1) {
    throw new NotFoundError('Book', id);
  }

  // Atualiza apenas os campos fornecidos (partial update).
  // Isso permite que o cliente envie apenas os campos que deseja alterar.
  if (updates.title !== undefined) books[index].title = updates.title;
  if (updates.author !== undefined) books[index].author = updates.author;
  if (updates.year !== undefined) books[index].year = updates.year;
  if (updates.genre !== undefined) books[index].genre = updates.genre;

  // Sempre atualiza o timestamp de modificação.
  books[index].updatedAt = new Date().toISOString();

  return books[index];
}

/**
 * Exclui um livro pelo ID.
 *
 * @param {number|string} id — ID do livro a excluir.
 * @returns {boolean} true se excluído com sucesso, false caso contrário.
 * @throws {NotFoundError} Se o livro não for encontrado.
 */
function deleteBook(id) {
  const index = books.findIndex(book => book.id === Number(id));

  if (index === -1) {
    throw new NotFoundError('Book', id);
  }

  books.splice(index, 1); // Remove exatamente um elemento no índice encontrado.
  return true;
}

/**
 * Calcula estatísticas agregadas sobre o acervo de livros.
 *
 * As estatísticas retornadas incluem:
 *   - totalBooks: quantidade total de livros cadastrados.
 *   - averageYear: média dos anos de publicação (null se vazio).
 *   - booksByGenre: contagem de livros por gênero.
 *     Gêneros sem valor são agrupados como "Unknown".
 *   - booksByAuthor: contagem de livros por autor.
 *     Autores sem valor são agrupados como "Unknown".
 *
 * @returns {Object} Estatísticas do acervo.
 */
function getStats() {
  const totalBooks = books.length;

  // Filtra apenas livros com ano definido para calcular a média.
  const yearsWithData = books.filter(book => book.year !== null && book.year !== undefined);
  const averageYear = yearsWithData.length > 0
    ? yearsWithData.reduce((sum, book) => sum + book.year, 0) / yearsWithData.length
    : null;

  // Agrupamento por gênero usando reduce para eficiência O(n).
  const booksByGenre = books.reduce((acc, book) => {
    const genre = book.genre || 'Unknown';
    acc[genre] = (acc[genre] || 0) + 1;
    return acc;
  }, {});

  // Agrupamento por autor usando reduce para eficiência O(n).
  const booksByAuthor = books.reduce((acc, book) => {
    const author = book.author || 'Unknown';
    acc[author] = (acc[author] || 0) + 1;
    return acc;
  }, {});

  return {
    totalBooks,
    averageYear: averageYear ? Math.round(averageYear * 100) / 100 : null, // Arredonda para 2 casas decimais.
    booksByGenre,
    booksByAuthor,
  };
}

/**
 * Exporta todas as funções e classes como módulo CommonJS.
 *
 * POR QUE USAR MÓDULOS COMMONJS (require/module.exports)?
 * ------------------------------------------------------
 * O Node.js usa CommonJS por padrão. Embora ES Modules (import/export)
 * sejam o futuro, CommonJS ainda é amplamente usado e não requer
 * configuração adicional no package.json ("type": "module").
 */
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
  ValidationError,
  NotFoundError,
};
```

