## Arquivo 3: `src/middleware/errorHandler.js`

```javascript
/**
 * ============================================================
 * MIDDLEWARE — Tratamento Centralizado de Erros
 * ============================================================
 *
 * POR QUE UM MIDDLEWARE DE ERRO CENTRALIZADO?
 * -------------------------------------------
 * Em vez de repetir blocos try/catch em cada rota, um middleware
 * de erro centralizado:
 *   1. Reduz duplicação de código.
 *    2. Garante consistência no formato das respostas de erro.
 *   3. Captura erros lançados por middlewares anteriores na cadeia.
 *
 * COMO O EXPRESS IDENTIFICA UM MIDDLEWARE DE ERRO?
 * ------------------------------------------------
 * Middlewares de erro têm EXATAMENTE 4 parâmetros:
 *   (error, req, res, next)
 * O Express usa a assinatura para diferenciá-los de middlewares normais.
 * Se um middleware normal tiver 4 parâmetros, o Express o tratará como
 * handler de erro — isso é uma convenção intencional da biblioteca.
 *
 * A ordem de registro importa: middlewares de erro devem ser registrados
 * APÓS todas as rotas, para que possam capturar erros de qualquer rota.
 */

/**
 * Middleware principal de tratamento de erros.
 *
 * @param {Error} err — O erro lançado por uma rota ou middleware anterior.
 * @param {import('express').Request} req — Objeto de requisição Express.
 * @param {import('express').Response} res — Objeto de resposta Express.
 * @param {import('express').NextFunction} next — Função para passar ao próximo middleware.
 */
function errorHandler(err, req, res, next) {
  // Define o status HTTP com base no tipo de erro.
  // Se o erro já tiver statusCode definido (ex: ValidationError, NotFoundError),
  // usamos esse valor; caso contrário, assumimos 500 (Internal Server Error).
  const statusCode = err.statusCode || 500;

  // Estrutura padronizada de resposta de erro.
  // Isso garante que todos os erros tenham o mesmo formato para o cliente.
  const errorResponse = {
    success: false,
    error: {
      name: err.name || 'Error',
      message: err.message,
    },
    timestamp: new Date().toISOString(),
  };

  // Inclui detalhes de validação apenas se existirem (erro 400).
  // Isso evita expor informações desnecessárias em erros genéricos.
  if (err.details && Array.isArray(err.details)) {
    errorResponse.error.details = err.details;
  }

  // Em desenvolvimento, incluímos o stack trace para facilitar a depuração.
  // Em produção, isso seria desativado para não expor detalhes internos.
  if (process.env.NODE_ENV !== 'production') {
    errorResponse.stack = err.stack;
  }

  // Envia a resposta com o status apropriado e o corpo padronizado.
  res.status(statusCode).json(errorResponse);
}

/**
 * Middleware para capturar erros de rotas assíncronas.
 *
 * PROBLEMA RESOLVIDO:
 * ------------------
 * O Express não captura automaticamente rejeições de promessas em rotas
 * async/await. Se uma rota assíncrona lança um erro, o Express não o
 * encaminha para o middleware de erro, causando um "UnhandledPromiseRejection".
 *
 * SOLUÇÃO:
 * --------
 * Envolvemos a função do roteador com uma função que captura rejeições
 * e as passa para next(error), permitindo que o errorHandler centralizado
 * trate o erro corretamente.
 *
 * @param {Function} fn — Função assíncrona do roteador.
 * @returns {Function} Função envoltória que captura erros assíncronos.
 */
function asyncErrorHandler(fn) {
  return function (req, res, next) {
    // Promise.prototype.catch é chamado automaticamente quando a função
    // assíncrona rejeita. Passamos o erro para next(), que encadeia ao errorHandler.
    Promise.resolve(fn(req, res, next)).catch(next);
  };
}

module.exports = {
  errorHandler,
  asyncErrorHandler,
};
```

