## Arquivo 4: `src/routes/books.js`

```javascript
/**
 * ============================================================
 * ROTAS — Endpoints REST para recursos /books e /stats
 * ============================================================
 *
 * CONVENÇÕES REST ADOTADAS:
 * -------------------------
 * 1. Nomes de rotas usam substantivos no plural (/books), não verbos.
 *    Isso segue a convenção HTTP de que o método (GET/POST/PUT/DELETE)
 *    já indica a ação, e a URL deve indicar O QUÊ.
 *
 * 2. IDs na URL usam parâmetros de rota (:id), não query strings.
 *    Ex: /books/42 em vez de /books?id=42. Isso é mais limpo e segue
 *    a especificação URI do RFC 3986.
 *
 * 3. Métodos HTTP mapeiam para operações CRUD:
 *    GET    → leitura (listagem ou busca)
 *    POST   → criação
 *    PUT    → atualização completa (substituição)
 *    DELETE → remoção
 *
 * 4. Respostas seguem o padrão:
 *    - Sucesso: corpo JSON com os dados, status 2xx.
 *    - Erro: corpo JSON padronizado, status 4xx/5xx.
 *
 * FILTRAGEM NA LISTAGEM (GET /books):
 * -----------------------------------
 * Implementamos filtragem por query parameters para demonstrar como
 * APIs REST reais permitem refinamento de resultados sem criar
 * múltiplos endpoints. Isso segue o princípio de hipermedia: um único
 * recurso com múltiplas formas de visualização.
 */

const express = require('express');
const router = express.Router(); // Cria um roteador isolado para reutilização.

// Importa funções do model e classes de erro.
const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
  ValidationError,
  NotFoundError,
} = require('../models/book');

// Importa o handler assíncrono para capturar erros em rotas async.
const { asyncErrorHandler } = require('../middleware/errorHandler');

// ============================================================
// GET /books — Listar todos os livros (com filtragem opcional)
// ============================================================
//
// Exemplos de uso:
//   curl http://localhost:3000/books
//   curl "http://localhost:3000/books?author=J.K.Rowling"
//   curl "http://localhost:3000/books?genre=Ficção+Científica"
//   curl "http://localhost:3000/books?year=2000"
//   curl "http://localhost:3000/books?author=J.K.Rowling&genre=Fantasia"
//
// Postman: GET http://localhost:3000/books
//   Params tab: author = J.K.Rowling | genre = Fantasia

router.get(
  '/',
  asyncErrorHandler(async (req, res) => {
    // Obtém todos os livros do modelo.
    let result = getAllBooks();

    // Filtra por autor se o parâmetro "author" estiver presente na query string.
    // req.query é um objeto com todas as query parameters como strings.
    if (req.query.author) {
      const authorFilter = req.query.author.toLowerCase();
      result = result.filter(book =>
        book.author.toLowerCase().includes(authorFilter)
      );
    }

    // Filtra por gênero se o parâmetro "genre" estiver presente.
    if (req.query.genre) {
      const genreFilter = req.query.genre.toLowerCase();
      result = result.filter(book =>
        (book.genre || 'unknown').toLowerCase().includes(genreFilter)
      );
    }

    // Filtra por ano se o parâmetro "year" estiver presente.
    if (req.query.year) {
      const yearFilter = Number(req.query.year);
      result = result.filter(book => book.year === yearFilter);
    }

    // Retorna 200 OK com a lista de livros.
    // Usamos res.json() que serializa automaticamente para JSON e define
    // o header Content-Type como application/json.
    res.status(200).json({
      count: result.length, // Campo extra para informar quantidade ao cliente.
      data: result,
    });
  })
);

// ============================================================
// GET /books/:id — Obter um livro específico pelo ID
// ============================================================
//
// Exemplos de uso:
//   curl http://localhost:3000/books/1
//   curl http://localhost:3000/books/999  → retorna 404
//
// Postman: GET http://localhost:3000/books/1

router.get(
  '/:id',
  asyncErrorHandler(async (req, res) => {
    // Busca o livro pelo ID nos parâmetros da rota.
    const book = getBookById(req.params.id);

    if (!book) {
      // Lançamos NotFoundError para que o middleware de erro trate
      // a resposta com status 404 e corpo padronizado.
      throw new NotFoundError('Book', req.params.id);
    }

    res.status(200).json(book);
  })
);

// ============================================================
// POST /books — Criar um novo livro
// ============================================================
//
// Exemplos de uso:
//   curl -X POST http://localhost:3000/books \
//        -H "Content-Type: application/json" \
//        -d '{"title":"O Senhor dos Anéis","author":"J.R.R. Tolkien","year":1954,"genre":"Fantasia"}'
//
// Postman: POST http://localhost:3000/books
//   Headers: Content-Type: application/json
//   Body (raw JSON): {"title":"...","author":"...","year":1954,"genre":"..."}

router.post(
  '/',
  asyncErrorHandler(async (req, res) => {
    const { title, author, year, genre } = req.body;

    // Validação dos campos obrigatórios.
    // Coletamos todos os erros antes de lançar, para que o cliente receba
    // a lista completa de problemas de uma vez (fail-fast por campo).
    const validationDetails = [];

    if (!title || typeof title !== 'string' || title.trim() === '') {
      validationDetails.push({
        field: 'title',
        message: 'O título é obrigatório e deve ser uma string não vazia.',
      });
    }

    if (!author || typeof author !== 'string' || author.trim() === '') {
      validationDetails.push({
        field: 'author',
        message: 'O autor é obrigatório e deve ser uma string não vazia.',
      });
    }

    // Validação opcional do ano (se fornecido, deve ser um número válido).
    if (year !== undefined && year !== null) {
      const yearNum = Number(year);
      if (isNaN(yearNum) || !Number.isInteger(yearNum) || yearNum < 0 || yearNum > new Date().getFullYear() + 1) {
        validationDetails.push({
          field: 'year',
          message: 'O ano deve ser um número inteiro válido entre 0 e o ano atual + 1.',
        });
      }
    }

    // Se houver erros de validação, lançamos ValidationError com todos os detalhes.
    if (validationDetails.length > 0) {
      throw new ValidationError('Validação falhou: campos obrigatórios ausentes ou inválidos.', validationDetails);
    }

    // Cria o livro no modelo e obtém o objeto completo (com ID, timestamps, etc.).
    const newBook = createBook({ title, author, year, genre });

    // Retorna 201 Created com o recurso criado.
    // 201 é o status HTTP semântico para "recurso recém-criado".
    res.status(201).json(newBook);
  })
);

// ============================================================
// PUT /books/:id — Atualizar completamente um livro existente
// ============================================================
//
// Exemplos de uso:
//   curl -X PUT http://localhost:3000/books/1 \
//        -H "Content-Type: application/json" \
//        -d '{"title":"Novo Título","author":"Novo Autor"}'
//
// Postman: PUT http://localhost:3000/books/1
//   Headers: Content-Type: application/json
//   Body (raw JSON): {"title":"...","author":"..."}

router.put(
  '/:id',
  asyncErrorHandler(async (req, res) => {
    const book = getBookById(req.params.id);

    if (!book) {
      throw new NotFoundError('Book', req.params.id);
    }

    // Atualiza apenas os campos fornecidos no corpo da requisição.
    // Campos não enviados permanecem com seus valores anteriores.
    const updates = {};
    if (req.body.title !== undefined) updates.title = req.body.title;
    if (req.body.author !== undefined) updates.author = req.body.author;
    if (req.body.year !== undefined) updates.year = Number(req.body.year);
    if (req.body.genre !== undefined) updates.genre = req.body.genre;

    // Reutilizamos a validação do POST para manter consistência.
    const validationDetails = [];

    if (!updates.title || typeof updates.title !== 'string' || updates.title.trim() === '') {
      validationDetails.push({ field: 'title', message: 'O título é obrigatório.' });
    }
    if (!updates.author || typeof updates.author !== 'string' || updates.author.trim() === '') {
      validationDetails.push({ field: 'author', message: 'O autor é obrigatório.' });
    }

    if (validationDetails.length > 0) {
      throw new ValidationError('Validação falhou.', validationDetails);
    }

    const updatedBook = updateBook(req.params.id, updates);

    // Retorna 200 OK com o recurso atualizado.
    res.status(200).json(updatedBook);
  })
);

// ============================================================
// DELETE /books/:id — Excluir um livro pelo ID
// ============================================================
//
// Exemplos de uso:
//   curl -X DELETE http://localhost:3000/books/1
//   curl -X DELETE http://localhost:3000/books/999  → retorna 404
//
// Postman: DELETE http://localhost:3000/books/1

router.delete(
  '/:id',
  asyncErrorHandler(async (req, res) => {
    const book = getBookById(req.params.id);

    if (!book) {
      throw new NotFoundError('Book', req.params.id);
    }

    deleteBook(req.params.id);

    // Retorna 204 No Content — padrão REST para exclusão bem-sucedida.
    // 204 indica que a operação foi concluída, mas não há conteúdo para retornar.
    res.status(204).end();
  })
);

// ============================================================
// GET /stats — Estatísticas do acervo de livros
// ============================================================
//
// Exemplos de uso:
//   curl http://localhost:3000/stats
//
// Postman: GET http://localhost:3000/stats

router.get(
  '/stats',
  asyncErrorHandler(async (req, res) => {
    const stats = getStats();
    res.status(200).json(stats);
  })
);

module.exports = router;
```

