## Arquivo 5: `src/app.js`

```javascript
/**
 * ============================================================
 * APP — Configuração Central da Aplicação Express
 * ============================================================
 *
 * POR QUE SEPARAR app.js DO server.js?
 * ------------------------------------
 * - app.js configura o aplicativo (middlewares, rotas).
 * - server.js apenas inicia o servidor HTTP e define a porta.
 * Essa separação permite testar o app sem precisar iniciar um servidor.
 *
 * ORDEM DE REGISTRO DOS MIDDLEWARES:
 * ----------------------------------
 * 1. body-parser (express.json()) — deve vir ANTES das rotas para que
 *    req.body seja populado antes de qualquer handler ser executado.
 * 2. Rotas — registradas após os middlewares de parsing.
 * 3. errorHandler — registrado POR ÚLTIMO, para capturar erros de todas as rotas.
 */

const express = require('express');
const booksRouter = require('./routes/books');
const { errorHandler } = require('./middleware/errorHandler');

// Cria a instância do aplicativo Express.
const app = express();

// ============================================================
// MIDDLEWARES GLOBAIS
// ============================================================

/**
 * express.json() — Parser de corpo JSON.
 *
 * Sem este middleware, req.body seria undefined para requisições POST/PUT
 * com body JSON. O Express não faz parsing automático desde a versão 4.16+.
 */
app.use(express.json());

/**
 * Middleware de logging simples para depuração.
 *
 * Loga o método HTTP, URL e timestamp de cada requisição.
 * Em produção, substituiríamos por um logger profissional como Winston ou Pino.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next(); // Passa para o próximo middleware/rota.
});

// ============================================================
// ROTAS
// ============================================================

/**
 * Mounting do roteador de livros no caminho /books.
 *
 * Isso significa que todas as rotas definidas em routes/books.js
 * serão acessíveis sob o prefixo /books:
 *   /books          → GET (listar), POST (criar)
 *   /books/:id      → GET, PUT, DELETE
 *   /books/stats    → GET (estatísticas)
 */
app.use('/books', booksRouter);

// ============================================================
// ROTA PADRÃO — Health Check
// ============================================================

/**
 * GET / — Verifica se a API está respondendo.
 * Útil para health checks de orquestradores como Kubernetes ou Docker Swarm.
 */
app.get('/', (req, res) => {
  res.json({
    name: 'Book API',
    version: '1.0.0',
    description: 'API REST para gerenciamento de livros — exemplo educacional',
    endpoints: {
      list: 'GET /books',
      create: 'POST /books',
      getById: 'GET /books/:id',
      update: 'PUT /books/:id',
      delete: 'DELETE /books/:id',
      stats: 'GET /stats',
    },
  });
});

// ============================================================
// ROTA 404 — Tratamento de rotas inexistentes
// ============================================================

/**
 * Captura qualquer rota não definida e retorna 404.
 *
 * Esta rota deve ser registrada APÓS todas as outras rotas,
 * para que tenha precedência menor.
 */
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: {
      name: 'NotFoundError',
      message: `Rota ${req.method} ${req.url} não encontrada`,
    },
    timestamp: new Date().toISOString(),
  });
});

// ============================================================
// MIDDLEWARE DE ERRO — Registrado por último
// ============================================================

/**
 * O errorHandler deve ser o ÚLTIMO middleware registrado.
 * Ele captura erros de todas as rotas e middlewares anteriores.
 */
app.use(errorHandler);

module.exports = app;
```

