## Arquivo 6: `src/server.js`

```javascript
/**
 * ============================================================
 * SERVER — Ponto de Entrada da Aplicação
 * ============================================================
 *
 * Este arquivo é o ponto de entrada (main) do aplicativo.
 * Sua única responsabilidade é iniciar o servidor HTTP na porta configurada.
 */

const app = require('./app');

// Porta padrão: 3000, mas permite sobrescrita via variável de ambiente PORT.
// Isso é essencial para ambientes de containerização (Docker, Kubernetes)
// que injetam a porta disponível via variável de ambiente.
const PORT = process.env.PORT || 3000;

// Inicia o servidor HTTP e loga na inicialização.
const server = app.listen(PORT, () => {
  console.log(`========================================`);
  console.log(`  Book API rodando em http://localhost:${PORT}`);
  console.log(`  Endpoints disponíveis:`);
  console.log(`    GET    /books          — Listar livros`);
  console.log(`    POST   /books          — Criar livro`);
  console.log(`    GET    /books/:id      — Buscar livro por ID`);
  console.log(`    PUT    /books/:id      — Atualizar livro`);
  console.log(`    DELETE /books/:id      — Excluir livro`);
  console.log(`    GET    /stats          — Estatísticas`);
  console.log(`========================================`);
});

// Captura erros de escuta do servidor (ex: porta já em uso).
server.on('error', (err) => {
  console.error(`Erro ao iniciar o servidor: ${err.message}`);
  process.exit(1); // Sai com código de erro para que o processo não continue silenciosamente.
});

module.exports = server;
```

