## File 2: `server.js`

```javascript
/**
 * ============================================================================
 * BOOK REST API — SERVER ENTRY POINT
 * ============================================================================
 *
 * This file bootstraps the Express application, configures middleware,
 * mounts route handlers, and installs a centralized error-handling pipeline.
 *
 * DESIGN DECISIONS:
 * 1. We use `express.json()` to automatically parse incoming JSON request bodies.
 *    Without this, req.body would be undefined for POST/PUT requests.
 *
 * 2. CORS middleware is placed BEFORE route handlers so that cross-origin
 *    preflight (OPTIONS) requests are handled correctly.
 *
 * 3. Error-handling middleware in Express is identified by its signature:
 *    (err, req, res, next) => ...  Express uses arity detection to distinguish
 *    error middleware from regular middleware. It MUST be registered last so
 *    that all routes have a chance to call next(err) before the handler runs.
 *
 * 4. We use async/await throughout because it produces linear, readable code
 *    compared to callback chains or .then() promises. Express natively supports
 *    async route handlers (v4.16+), so we do not need try/catch wrappers in
 *    every handler — errors bubble up to the error middleware automatically.
 * ============================================================================
 */

const express = require('express');
const cors = require('cors');

// --------------------------------------------------------------------------
// 1. APPLICATION INITIALIZATION
// --------------------------------------------------------------------------
// `express()` creates a new Express application instance. This is the core
// object that holds our middleware, routes, and configuration.
const app = express();

// --------------------------------------------------------------------------
// 2. MIDDLEWARE CONFIGURATION
// --------------------------------------------------------------------------

/**
 * CORS (Cross-Origin Resource Sharing) middleware.
 *
 * Why we need it: Browsers enforce the Same-Origin Policy, which blocks
 * frontend code running on one origin (e.g., localhost:3000) from making
 * requests to a different origin (e.g., localhost:5000). The `cors` package
 * adds the necessary HTTP headers (Access-Control-Allow-Origin, etc.) so
 * that browsers allow these cross-origin requests.
 *
 * Options: `{ origin: '*' }` allows any origin. In production, you would
 * restrict this to specific trusted domains for security.
 */
app.use(cors({ origin: '*' }));

/**
 * JSON body-parsing middleware.
 *
 * Why we need it: Express does NOT parse request bodies by default. The
 * `express.json()` middleware reads the raw request body, parses JSON strings
 * into JavaScript objects, and attaches the result to `req.body`. Without it,
 * POST/PUT requests with JSON payloads would have `req.body === undefined`.
 *
 * This middleware runs on every request that has a Content-Type of
 * application/json. Requests without that header are passed through unchanged.
 */
app.use(express.json());

/**
 * Request logging middleware (development aid).
 *
 * Why we include it: Logging every incoming request helps with debugging and
 * understanding the flow of traffic through the API. In production, you would
 * typically use a dedicated logging library (e.g., winston, pino).
 *
 * The `next()` call is critical — it passes control to the next middleware
 * or route handler. Forgetting `next()` would hang the request indefinitely.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next(); // MUST call next() to continue the middleware chain
});

// --------------------------------------------------------------------------
// 3. ROUTE MOUNTING
// --------------------------------------------------------------------------

/**
 * Import route handlers from a separate module.
 *
 * Why we separate routes into their own file: As the API grows, keeping all
 * route definitions in server.js becomes unwieldy. Separation of concerns
 * makes the codebase easier to navigate, test, and maintain. The `require()`
 * call loads the module and returns the Express Router instance.
 */
const bookRoutes = require('./routes/books');

/**
 * Mount the books router at the `/books` path prefix.
 *
 * Why we use a router: `app.use('/books', bookRoutes)` tells Express to
 * prepend `/books` to every route defined in the books module. So a route
 * defined as `router.get('/:id')` inside books.js becomes accessible at
 * `/books/:id`. This keeps path definitions DRY and organized.
 */
app.use('/books', bookRoutes);

/**
 * Root endpoint for API discovery / health check.
 *
 * Why we include it: A simple root endpoint lets consumers verify the API is
 * running and discover available endpoints. It's a common REST convention.
 */
app.get('/', (req, res) => {
  res.json({
    name: 'Book REST API',
    version: '1.0.0',
    description: 'Educational REST API for managing books',
    endpoints: {
      'GET /books': 'List all books (supports filtering)',
      'GET /books/stats': 'Return aggregate statistics',
      'GET /books/:id': 'Get a single book by ID',
      'POST /books': 'Create a new book',
      'PUT /books/:id': 'Update an existing book (full replacement)',
      'DELETE /books/:id': 'Delete a book by ID'
    }
  });
});

// --------------------------------------------------------------------------
// 4. CUSTOM ERROR CLASSES
// --------------------------------------------------------------------------

/**
 * Base error class for all API errors.
 *
 * Why we extend `Error`: JavaScript's built-in `Error` class provides a
 * standard stack trace and message property. By extending it, our custom
 * errors inherit this behavior while allowing us to attach additional
 * properties (like `statusCode` and `isOperational`).
 *
 * `isOperational` is a convention used to distinguish between expected
 * application errors (e.g., "book not found") and unexpected bugs
 * (e.g., null reference exceptions). Operational errors should NOT
 * trigger alerting; non-operational errors indicate a bug that needs fixing.
 */
class BaseError extends Error {
  /**
   * @param {string} message - Human-readable error description
   * @param {number} statusCode - HTTP status code (default: 500)
   * @param {boolean} isOperational - Whether this is an expected app error
   */
  constructor(message, statusCode = 500, isOperational = true) {
    super(message); // Call parent constructor to set .message and capture stack

    // `Object.setPrototypeOf` ensures instanceof checks work correctly with
    // custom classes. Without it, `err instanceof BaseError` would return false.
    Object.setPrototypeOf(this, BaseError.prototype);

    this.statusCode = statusCode;
    this.isOperational = isOperational;

    // Capture a clean stack trace (exclude the constructor call itself)
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * 404 Not Found — Resource does not exist.
 */
class NotFoundError extends BaseError {
  constructor(resource = 'Resource') {
    super(`${resource} not found`, 404, true);
  }
}

/**
 * 400 Bad Request — Invalid input data.
 */
class ValidationError extends BaseError {
  constructor(message = 'Validation failed') {
    super(message, 400, true);
  }
}

/**
 * 409 Conflict — Resource already exists.
 */
class ConflictError extends BaseError {
  constructor(message = 'Resource already exists') {
    super(message, 409, true);
  }
}

// --------------------------------------------------------------------------
// 5. CENTRALIZED ERROR-HANDLING MIDDLEWARE
// --------------------------------------------------------------------------

/**
 * Global error-handling middleware.
 *
 * WHY THIS PATTERN: Express provides a special middleware signature for
 * error handling: `(err, req, res, next)`. Express detects this by counting
 * parameters (arity). This middleware MUST be registered AFTER all routes
 * so that any route can throw or pass an error to it via `next(err)`.
 *
 * HOW IT WORKS:
 * - If an async route handler throws an error, Express catches it and
 *   passes it here automatically.
 * - If a route calls `next(new NotFoundError())`, the error is passed here.
 * - We check `err.isOperational` to decide whether to log silently or
 *   alert on unexpected bugs.
 *
 * SECURITY NOTE: In production, never send the full error object to the
 * client. Only send `statusCode` and `message`. The `stack` property may
 * contain sensitive file paths and should only be logged server-side.
 */
app.use((err, req, res, next) => {
  // Log the full error (including stack) server-side for debugging
  const LogLevel = err.isOperational ? 'WARN' : 'ERROR';
  console.log(`[${LogLevel}] ${err.name}: ${err.message}`);
  if (!err.isOperational) {
    console.error(err.stack); // Print full stack trace for unexpected bugs
  }

  // Build a consistent JSON error response
  res.status(err.statusCode || 500).json({
    success: false,
    error: {
      message: err.message,
      // Only include stack in development for debugging
      stack: process.env.NODE_ENV !== 'production' ? err.stack : undefined
    }
  });
});

// --------------------------------------------------------------------------
// 6. 404 HANDLER FOR UNMATCHED ROUTES
// --------------------------------------------------------------------------

/**
 * Catch-all middleware for requests that don't match any route.
 *
 * WHY THIS IS NEEDED: If a client requests `/books/999` and no route matches,
 * Express would normally respond with a generic "Cannot GET /books/999" HTML
 * page. This middleware intercepts all unmatched routes and returns a proper
 * JSON 404 response instead, maintaining API consistency.
 *
 * Placement: This must come AFTER all route definitions so that legitimate
 * routes are matched first.
 */
app.use((req, res, next) => {
  res.status(404).json({
    success: false,
    error: {
      message: `Route ${req.method} ${req.url} not found`
    }
  });
});

// --------------------------------------------------------------------------
// 7. SERVER STARTUP
// --------------------------------------------------------------------------

/**
 * Start the HTTP server and listen on the configured port.
 *
 * WHY WE USE `process.env.PORT || 5000`: This is a standard Node.js pattern
 * that allows deployment platforms (Heroku, Railway, etc.) to override the
 * port via environment variables while defaulting to 5000 for local development.
 */
const PORT = process.env.PORT || 5000;

app.listen(PORT, () => {
  console.log(`📚 Book API running on http://localhost:${PORT}`);
  console.log(`📖 Try: curl http://localhost:${PORT}/books`);
});
```

