## File 3: `routes/books.js`

```javascript
/**
 * ============================================================================
 * BOOK ROUTES — CRUD OPERATIONS
 * ============================================================================
 *
 * This module defines all REST endpoints for the /books resource.
 * It uses an in-memory array as its data store (for educational purposes).
 *
 * DATA STRUCTURE CHOICES:
 * 1. In-memory array (`let books = [...]`): Chosen for simplicity and to avoid
 *    external dependencies. In a real application, you would use a database
 *    (PostgreSQL, MongoDB, etc.) with proper indexing and persistence.
 *
 * 2. Sequential numeric IDs: Simple and predictable. UUIDs or ObjectId would
 *    be better for distributed systems to avoid collisions.
 *
 * 3. `let` instead of `const` for the array: We need to reassign the variable
 *    when we want to replace the entire array (e.g., during stats computation).
 *    Using `const` would prevent reassignment but still allow mutation of
 *    array contents (push, splice), so either works. We use `let` for clarity.
 *
 * REST CONVENTIONS USED:
 * - GET    /books       → List all (with optional query filters)
 * - GET    /books/:id   → Retrieve one by ID
 * - POST   /books       → Create a new resource
 * - PUT    /books/:id   → Full update/replace of a resource
 * - DELETE /books/:id   → Remove a resource
 * - GET    /books/stats → Aggregate statistics (non-standard, but useful)
 * ============================================================================
 */

const express = require('express');

// --------------------------------------------------------------------------
// 1. ROUTER & DATA STORE
// --------------------------------------------------------------------------

/**
 * Create an Express Router instance.
 *
 * Why a Router: Routers are mini-applications that can have their own
 * middleware, routes, and error handlers. They can be mounted at a path
 * prefix (done in server.js with `app.use('/books', bookRoutes)`).
 */
const router = express.Router();

/**
 * In-memory book storage.
 *
 * Each book object has the following shape:
 * {
 *   id: number,          // Unique sequential identifier
 *   title: string,       // Book title
 *   author: string,      // Author name
 *   year: number,        // Publication year
 *   genre: string        // Genre/category (e.g., "Fiction", "Science")
 * }
 *
 * WHY AN ARRAY? Arrays provide O(1) access by index and support efficient
 * iteration for filtering. For a real application with thousands of records,
 * a Map or database would be more appropriate for O(1) lookups by ID.
 */
let books = [
  { id: 1, title: 'To Kill a Mockingbird', author: 'Harper Lee', year: 1960, genre: 'Fiction' },
  { id: 2, title: 'A Brief History of Time', author: 'Stephen Hawking', year: 1988, genre: 'Science' },
  { id: 3, title: 'The Great Gatsby', author: 'F. Scott Fitzgerald', year: 1925, genre: 'Fiction' },
  { id: 4, title: 'Sapiens', author: 'Yuval Noah Harari', year: 2011, genre: 'History' },
  { id: 5, title: 'The Hobbit', author: 'J.R.R. Tolkien', year: 1937, genre: 'Fantasy' }
];

/**
 * Track the next ID to assign for new books.
 *
 * WHY A SEPARATE COUNTER: Using `books.length + 1` could produce duplicate
 * IDs if books are deleted. A dedicated counter ensures uniqueness.
 */
let nextId = 6;

// --------------------------------------------------------------------------
// 2. VALIDATION HELPERS
// --------------------------------------------------------------------------

/**
 * Validate required fields for book creation/update.
 *
 * @param {Object} data - The request body to validate
 * @returns {string|null} Error message if invalid, null if valid
 *
 * WHY SEPARATE VALIDATION: Keeping validation logic in a dedicated function
 * makes it reusable across POST (create) and PUT (update) handlers. It also
 * keeps route handlers focused on routing concerns rather than business logic.
 */
function validateBookData(data) {
  const errors = [];

  // Check that title is provided and is a non-empty string
  if (!data.title || typeof data.title !== 'string' || data.title.trim() === '') {
    errors.push('title is required and must be a non-empty string');
  }

  // Check that author is provided and is a non-empty string
  if (!data.author || typeof data.author !== 'string' || data.author.trim() === '') {
    errors.push('author is required and must be a non-empty string');
  }

  // Year must be a positive integer (publication year)
  if (data.year === undefined || data.year === null) {
    errors.push('year is required');
  } else if (!Number.isInteger(data.year) || data.year < 1000 || data.year > new Date().getFullYear() + 1) {
    errors.push('year must be a valid integer between 1000 and current year+1');
  }

  // Genre is optional but must be a string if provided
  if (data.genre !== undefined && typeof data.genre !== 'string') {
    errors.push('genre must be a string if provided');
  }

  return errors.length > 0 ? errors.join('; ') : null;
}

/**
 * Validate that an ID parameter is a positive integer.
 *
 * @param {string} idStr - The URL parameter as a string
 * @returns {number|null} Parsed integer ID, or null if invalid
 */
function parseBookId(idStr) {
  const id = parseInt(idStr, 10);
  return Number.isInteger(id) && id > 0 ? id : null;
}

// --------------------------------------------------------------------------
// 3. GET /books — LIST ALL BOOKS (WITH FILTERING)
// --------------------------------------------------------------------------

/**
 * GET /books
 *
 * Retrieve all books, with optional query-parameter filtering.
 *
 * QUERY PARAMETERS (all optional):
 * - title    : Filter by title substring (case-insensitive)
 * - author   : Filter by author substring (case-insensitive)
 * - genre    : Exact match on genre
 * - yearFrom : Minimum publication year (inclusive)
 * - yearTo   : Maximum publication year (inclusive)
 *
 * EXAMPLES:
 *   GET /books                          → All books
 *   GET /books?genre=Fiction            → Only Fiction books
 *   GET /books?title=gatsby&author=fitzgerald  → Books matching both
 *   GET /books?yearFrom=1950&yearTo=2000 → Books published 1950-2000
 *
 * curl: curl http://localhost:5000/books?genre=Fiction
 */
router.get('/', (req, res) => {
  // Start with the full collection
  let result = books;

  // Apply title filter (case-insensitive substring match)
  if (req.query.title) {
    const searchTerm = req.query.title.toLowerCase();
    result = result.filter(book => book.title.toLowerCase().includes(searchTerm));
  }

  // Apply author filter (case-insensitive substring match)
  if (req.query.author) {
    const searchTerm = req.query.author.toLowerCase();
    result = result.filter(book => book.author.toLowerCase().includes(searchTerm));
  }

  // Apply exact genre match
  if (req.query.genre) {
    result = result.filter(book => book.genre === req.query.genre);
  }

  // Apply year range filter (inclusive on both ends)
  if (req.query.yearFrom) {
    const minYear = parseInt(req.query.yearFrom, 10);
    result = result.filter(book => book.year >= minYear);
  }
  if (req.query.yearTo) {
    const maxYear = parseInt(req.query.yearTo, 10);
    result = result.filter(book => book.year <= maxYear);
  }

  // Return the (possibly filtered) results with a count for convenience
  res.json({
    success: true,
    count: result.length,
    total: books.length,
    data: result
  });
});

// --------------------------------------------------------------------------
// 4. GET /books/stats — AGGREGATE STATISTICS
// --------------------------------------------------------------------------

/**
 * GET /books/stats
 *
 * Return aggregate statistics about the book collection.
 *
 * Statistics computed:
 * - totalBooks       : Total number of books
 * - averageYear      : Average publication year (rounded to 2 decimals)
 * - genreDistribution: Count of books per genre
 * - oldestBook       : Book with the earliest publication year
 * - newestBook       : Book with the latest publication year
 *
 * curl: curl http://localhost:5000/books/stats
 */
router.get('/stats', (req, res) => {
  if (books.length === 0) {
    return res.json({
      success: true,
      data: {
        totalBooks: 0,
        averageYear: null,
        genreDistribution: {},
        oldestBook: null,
        newestBook: null
      }
    });
  }

  // Compute genre distribution using reduce
  const genreDistribution = books.reduce((acc, book) => {
    acc[book.genre] = (acc[book.genre] || 0) + 1;
    return acc;
  }, {});

  // Find oldest and newest books
  const oldestBook = books.reduce((oldest, book) =>
    book.year < oldest.year ? book : oldest
  , books[0]);

  const newestBook = books.reduce((newest, book) =>
    book.year > newest.year ? book : newest
  , books[0]);

  // Compute average year
  const totalYear = books.reduce((sum, book) => sum + book.year, 0);
  const averageYear = Math.round((totalYear / books.length) * 100) / 100;

  res.json({
    success: true,
    data: {
      totalBooks: books.length,
      averageYear,
      genreDistribution,
      oldestBook,
      newestBook
    }
  });
});

// --------------------------------------------------------------------------
// 5. GET /books/:id — GET SINGLE BOOK BY ID
// --------------------------------------------------------------------------

/**
 * GET /books/:id
 *
 * Retrieve a single book by its numeric ID.
 *
 * PATH PARAMETER:
 * - id : Positive integer book identifier
 *
 * RESPONSES:
 * - 200 : Book found
 * - 400 : Invalid ID format
 * - 404 : Book not found
 *
 * curl: curl http://localhost:5000/books/1
 */
router.get('/:id', (req, res, next) => {
  // Parse and validate the ID parameter
  const id = parseBookId(req.params.id);
  if (id === null) {
    // Pass error to centralized handler via next(err)
    return next(new ValidationError('Invalid book ID. Must be a positive integer.'));
  }

  // Find the book by ID using Array.find (O(n) search)
  const book = books.find(b => b.id === id);

  if (!book) {
    // NotFoundError is a custom error with statusCode=404
    return next(new NotFoundError('Book'));
  }

  res.json({ success: true, data: book });
});

// --------------------------------------------------------------------------
// 6. POST /books — CREATE NEW BOOK
// --------------------------------------------------------------------------

/**
 * POST /books
 *
 * Create a new book and add it to the collection.
 *
 * REQUEST BODY (JSON):
 * {
 *   "title": "The Catcher in the Rye",
 *   "author": "J.D. Salinger",
 *   "year": 1951,
 *   "genre": "Fiction"    // optional
 * }
 *
 * RESPONSES:
 * - 201 : Book created successfully (with Location header)
 * - 400 : Validation error
 *
 * curl: curl -X POST http://localhost:5000/books \
 *       -H "Content-Type: application/json" \
 *       -d '{"title":"The Catcher in the Rye","author":"J.D. Salinger","year":1951,"genre":"Fiction"}'
 */
router.post('/', (req, res, next) => {
  // Validate incoming data
  const validationError = validateBookData(req.body);
  if (validationError) {
    return next(new ValidationError(validationError));
  }

  // Create the new book object
  const newBook = {
    id: nextId++,
    title: req.body.title.trim(),
    author: req.body.author.trim(),
    year: parseInt(req.body.year, 10),
    genre: req.body.genre ? req.body.genre.trim() : ''
  };

  // Add to in-memory store
  books.push(newBook);

  // 201 Created is the standard REST status for resource creation.
  // The Location header points to the new resource's URI, following
  // REST best practices (HATEOAS principle).
  res.status(201).header('Location', `/books/${newBook.id}`).json({
    success: true,
    message: 'Book created successfully',
    data: newBook
  });
});

// --------------------------------------------------------------------------
// 7. PUT /books/:id — FULL UPDATE EXISTING BOOK
// --------------------------------------------------------------------------

/**
 * PUT /books/:id
 *
 * Fully replace an existing book's data. All required fields must be
 * provided in the request body.
 *
 * PATH PARAMETER:
 * - id : Positive integer book identifier
 *
 * REQUEST BODY (JSON):
 * {
 *   "title": "Updated Title",
 *   "author": "Updated Author",
 *   "year": 2020,
 *   "genre": "Fantasy"    // optional
 * }
 *
 * RESPONSES:
 * - 200 : Book updated successfully
 * - 400 : Invalid ID or validation error
 * - 404 : Book not found
 *
 * curl: curl -X PUT http://localhost:5000/books/1 \
 *       -H "Content-Type: application/json" \
 *       -d '{"title":"To Kill a Mockingbird (Updated)","author":"Harper Lee","year":1960,"genre":"Fiction"}'
 */
router.put('/:id', (req, res, next) => {
  // Validate ID
  const id = parseBookId(req.params.id);
  if (id === null) {
    return next(new ValidationError('Invalid book ID. Must be a positive integer.'));
  }

  // Find the book to update
  const bookIndex = books.findIndex(b => b.id === id);
  if (bookIndex === -1) {
    return next(new NotFoundError('Book'));
  }

  // Validate incoming data
  const validationError = validateBookData(req.body);
  if (validationError) {
    return next(new ValidationError(validationError));
  }

  // Replace the entire book object (PUT is a full replacement, not partial)
  books[bookIndex] = {
    id, // Preserve the original ID
    title: req.body.title.trim(),
    author: req.body.author.trim(),
    year: parseInt(req.body.year, 10),
    genre: req.body.genre ? req.body.genre.trim() : ''
  };

  res.json({
    success: true,
    message: 'Book updated successfully',
    data: books[bookIndex]
  });
});

// --------------------------------------------------------------------------
// 8. DELETE /books/:id — DELETE BOOK BY ID
// --------------------------------------------------------------------------

/**
 * DELETE /books/:id
 *
 * Permanently remove a book from the collection.
 *
 * PATH PARAMETER:
 * - id : Positive integer book identifier
 *
 * RESPONSES:
 * - 200 : Book deleted successfully (returns removed book)
 * - 400 : Invalid ID format
 * - 404 : Book not found
 *
 * curl: curl -X DELETE http://localhost:5000/books/3
 */
router.delete('/:id', (req, res, next) => {
  // Validate ID
  const id = parseBookId(req.params.id);
  if (id === null) {
    return next(new ValidationError('Invalid book ID. Must be a positive integer.'));
  }

  // Find the index of the book to delete
  const bookIndex = books.findIndex(b => b.id === id);
  if (bookIndex === -1) {
    return next(new NotFoundError('Book'));
  }

  // Remove the book from the array using splice (O(n) operation)
  const [deletedBook] = books.splice(bookIndex, 1);

  // 200 OK with the deleted resource is acceptable. Some APIs prefer 204 No
  // Content (no body), but returning the deleted object helps clients confirm
  // what was removed, which is useful for auditing and debugging.
  res.json({
    success: true,
    message: 'Book deleted successfully',
    data: deletedBook
  });
});

// --------------------------------------------------------------------------
// 9. EXPORT THE ROUTER
// --------------------------------------------------------------------------

/**
 * Export the router so it can be mounted in server.js.
 *
 * Why we export the router (not individual handlers): This follows the
 * Module pattern and keeps the routing logic encapsulated. The server.js
 * file mounts this router at `/books`, so all routes are automatically
 * prefixed.
 */
module.exports = router;
```

