## Arquivo 2: `src/errors/CustomError.js`

```javascript
/**
 * @fileoverview Classe base para erros personalizados da API.
 *
 * Por que criar classes de erro personalizadas?
 *   - Permitem distinguir tipos de erro no middleware de tratamento global.
 *   - Facilitam a resposta padronizada com código HTTP, mensagem e metadados.
 *   - Tornam o código mais legível ao usar `throw new NotFoundError(...)` em vez de
 *     retornar `{ status: 404 }` manualmente em cada rota.
 */

/**
 * Classe base para todos os erros da aplicação.
 * Extende Error nativo do Node.js para manter compatibilidade com stack traces.
 */
class AppError extends Error {
  /**
   * @param {string} message - Mensagem de erro legível pelo usuário.
   * @param {number} statusCode - Código HTTP correspondente (ex: 400, 404, 500).
   * @param {boolean} [isOperational=true] - Indica se o erro é esperado (falha de entrada)
   *                                         ou um bug interno do servidor. Erros operacionais
   *                                         não devem expor detalhes ao cliente.
   */
  constructor(message, statusCode, isOperational = true) {
    super(message); // Chama construtor da classe Error nativa

    this.statusCode = statusCode;
    this.isOperational = isOperational;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';

    // Captura o stack trace no ponto de criação do erro (não na instância Error)
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Erro 400 — Requisição inválida.
 * Usado quando os dados enviados pelo cliente não atendem aos requisitos do endpoint.
 */
class BadRequestError extends AppError {
  constructor(message = 'Requisição inválida') {
    super(message, 400);
  }
}

/**
 * Erro 404 — Recurso não encontrado.
 * Usado quando um ID informado não corresponde a nenhum registro na base.
 */
class NotFoundError extends AppError {
  constructor(resource = 'Recurso') {
    super(`${resource} não encontrado`, 404);
  }
}

/**
 * Erro 409 — Conflito de dados.
 * Usado quando uma operação viola uma restrição de unicidade (ex: duplicar ISBN).
 */
class ConflictError extends AppError {
  constructor(message = 'Conflito com recurso existente') {
    super(message, 409);
  }
}

/**
 * Erro 500 — Erro interno do servidor.
 * Usado para bugs não previstos. O middleware global decide se expõe detalhes ao cliente.
 */
class InternalServerError extends AppError {
  constructor(message = 'Erro interno do servidor') {
    super(message, 500, false); // false = erro NÃO operacional (bug)
  }
}

module.exports = { AppError, BadRequestError, NotFoundError, ConflictError, InternalServerError };
```

