## Arquivo 3: `src/middleware/errorHandler.js`

```javascript
/**
 * @fileoverview Middleware global de tratamento de erros.
 *
 * Por que um middleware centralizado?
 *   - Evita repetição de blocos try/catch em cada rota.
 *   - Garante resposta consistente independente de onde o erro ocorra.
 *   - Permite diferenciar erros operacionais (cliente) de bugs (servidor).
 *
 * Convenção Express: middlewares de erro têm 4 parâmetros (err, req, res, next).
 * O Express os reconhece automaticamente quando encadeados via app.use().
 */

const { InternalServerError } = require('../errors/CustomError');

/**
 * Middleware que captura erros lançados em rotas e middlewares.
 *
 * @param {Error} err - Instância de erro capturada.
 * @param {import('express').Request} req - Objeto Request do Express.
 * @param {import('express').Response} res - Objeto Response do Express.
 * @param {import('express').NextFunction} next - Função next do Express.
 */
function errorHandler(err, req, res, next) {
  // Se o erro não for uma instância de AppError, tratamos como erro interno inesperado
  if (!(err instanceof require('../errors/CustomError').AppError)) {
    console.error('[ERRO NÃO TRATADO]:', err); // Log para depuração (não exposto ao cliente)
    err = new InternalServerError('Algo inesperado ocorreu. Tente novamente mais tarde.');
  }

  // Monta resposta padronizada
  const response = {
    status: err.status,       // 'fail' para 4xx, 'error' para 5xx
    message: err.message,     // Mensagem legível pelo usuário
  };

  // Em ambiente de desenvolvimento, incluímos o stack trace para facilitar debugging
  if (process.env.NODE_ENV === 'development') {
    response.stack = err.stack;
  }

  // Log do erro no servidor (independente do ambiente)
  console.error(`[${err.statusCode}] ${err.message}`);

  // Envia resposta com o código HTTP correspondente
  res.status(err.statusCode).json(response);
}

/**
 * Middleware que captura erros de Promise rejeitada (async/await sem try/catch).
 *
 * Por que este middleware é necessário?
 *   - Quando usamos async nas rotas e esquecemos um try/catch, a rejeição da Promise
 *     não é capturada pelo Express automaticamente. Este wrapper resolve esse problema.
 *
 * @param {Function} fn - Função assíncrona da rota.
 * @returns {Function} Middleware Express.
 */
function asyncHandler(fn) {
  return (req, res, next) => {
    fn(req, res, next).catch(next); // Encaminha qualquer erro para o errorHandler
  };
}

module.exports = { errorHandler, asyncHandler };
```

