## Arquivo 4: `src/data/books.js`

```javascript
/**
 * @fileoverview Camada de dados — armazenamento em memória via array.
 *
 * Por que usar um array em vez de um objeto/map?
 *   - Arrays preservam a ordem de inserção, o que é útil para listagens paginadas.
 *   - A operação `findIndex` permite busca por ID com complexidade O(n), aceitável
 *     para volumes pequenos (educacional). Para escalabilidade, migraríamos para um Map.
 *
 * Por que não usar variáveis globais?
 *   - O array é exportado como módulo singleton. Node.js cacheia módulos, então todas
 *     as importações compartilham a mesma referência — comportamento equivalente a uma
 *     variável global, mas com encapsulamento explícito via módulo.
 *
 * Dados iniciais (seed) para testes imediatos sem precisar de POSTs manuais.
 */

/**
 * Array que armazena todos os livros em memória.
 * Cada livro é um objeto com propriedades bem definidas.
 *
 * @type {Array<{id: number, title: string, author: string, isbn: string, year: number, genre: string}>}
 */
const books = [
  {
    id: 1,
    title: 'O Senhor dos Anéis',
    author: 'J.R.R. Tolkien',
    isbn: '978-0-618-00221-3',
    year: 1954,
    genre: 'Fantasia',
  },
  {
    id: 2,
    title: '1984',
    author: 'George Orwell',
    isbn: '978-0-451-52493-5',
    year: 1949,
    genre: 'Distopia',
  },
  {
    id: 3,
    title: 'Dom Casmurro',
    author: 'Machado de Assis',
    isbn: '978-85-10-01234-5',
    year: 1899,
    genre: 'Romance',
  },
];

/**
 * Gera o próximo ID disponível com base no maior ID existente + 1.
 *
 * @returns {number} Próximo ID sequencial.
 */
function getNextId() {
  if (books.length === 0) return 1;
  // Math.max retorna -Infinity se o array estiver vazio, por isso o fallback
  return Math.max(...books.map((book) => book.id)) + 1;
}

module.exports = { books, getNextId };
```

