## Arquivo 5: `src/routes/books.js`

```javascript
/**
 * @fileoverview Rotas para recursos de livros (CRUD completo).
 *
 * Por que usar `express.Router()`?
 *   - Encapsula as rotas em um módulo reutilizável.
 *   - Permite aplicar middlewares específicos apenas a este conjunto de rotas.
 *   - Facilita a manutenção: todas as rotas de livros ficam em um único arquivo.
 *
 * Convenções REST adotadas:
 *   - GET    /books          → lista todos (com filtragem via query params)
 *   - GET    /books/:id      → obtém um livro pelo ID
 *   - POST   /books          → cria um novo livro
 *   - PUT    /books/:id      → atualiza completamente um livro existente
 *   - DELETE /books/:id      → exclui um livro
 *
 * Exemplos de uso (curl):
 *
 *   # Listar todos os livros
 *   curl http://localhost:3000/books
 *
 *   # Filtrar por gênero
 *   curl "http://localhost:3000/books?genre=Fantasia"
 *
 *   # Filtrar por autor (parcial)
 *   curl "http://localhost:3000/books?author=Tolkien"
 *
 *   # Obter livro por ID
 *   curl http://localhost:3000/books/1
 *
 *   # Criar novo livro
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"Duna","author":"Frank Herbert","isbn":"978-0-441-17271-9","year":1965,"genre":"Ficção Científica"}'
 *
 *   # Atualizar livro (PUT = substituição completa)
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"O Senhor dos Anéis","author":"J.R.R. Tolkien","isbn":"978-0-618-00221-3","year":1954,"genre":"Fantasia"}'
 *
 *   # Excluir livro
 *   curl -X DELETE http://localhost:3000/books/1
 */

const express = require('express');
const router = express.Router();

// Importação dos dados e utilitários
const { books, getNextId } = require('../data/books');
const { asyncHandler } = require('../middleware/errorHandler');
const { BadRequestError, NotFoundError, ConflictError } = require('../errors/CustomError');

/**
 * GET /books
 * Lista todos os livros com filtragem opcional por query params.
 *
 * Query params suportados:
 *   - genre  : filtra por gênero (correspondência exata)
 *   - author : filtra por autor (correspondência parcial, case-insensitive)
 *   - search : busca por título ou autor (correspondência parcial, case-insensitive)
 *
 * @example
 *   GET /books?genre=Fantasia
 *   GET /books?author=orwell
 *   GET /books?search=senhor
 */
router.get(
  '/',
  asyncHandler((req, res) => {
    const { genre, author, search } = req.query;

    let result = books;

    // Filtragem por gênero (exata)
    if (genre) {
      result = result.filter((book) => book.genre.toLowerCase() === genre.toLowerCase());
    }

    // Filtragem por autor (parcial, case-insensitive)
    if (author) {
      result = result.filter((book) =>
        book.author.toLowerCase().includes(author.toLowerCase())
      );
    }

    // Busca geral por título ou autor (parcial, case-insensitive)
    if (search) {
      const term = search.toLowerCase();
      result = result.filter(
        (book) =>
          book.title.toLowerCase().includes(term) ||
          book.author.toLowerCase().includes(term)
      );
    }

    // Resposta com metadados de paginação (útil para escalar no futuro)
    res.json({
      count: result.length,
      data: result,
      message: result.length === 0 ? 'Nenhum livro encontrado com os filtros aplicados.' : undefined,
    });
  })
);

/**
 * GET /books/:id
 * Obtém um único livro pelo ID.
 *
 * @param {number} params.id - ID numérico do livro.
 * @throws {NotFoundError} Se o livro não for encontrado.
 */
router.get(
  '/:id',
  asyncHandler((req, res) => {
    const id = parseInt(req.params.id, 10);

    // Validação básica do parâmetro
    if (isNaN(id)) {
      throw new BadRequestError('O parâmetro :id deve ser um número válido.');
    }

    const book = books.find((b) => b.id === id);

    if (!book) {
      throw new NotFoundError('Livro');
    }

    res.json({ data: book });
  })
);

/**
 * POST /books
 * Cria um novo livro a partir do corpo da requisição.
 *
 * Campos obrigatórios no body JSON:
 *   - title   (string) : Título do livro
 *   - author  (string) : Autor do livro
 *   - isbn    (string) : ISBN (deve ser único)
 *   - year    (number) : Ano de publicação
 *   - genre   (string) : Gênero literário
 *
 * @throws {BadRequestError} Se campos obrigatórios faltarem ou forem inválidos.
 * @throws {ConflictError}   Se o ISBN já estiver em uso.
 */
router.post(
  '/',
  asyncHandler((req, res) => {
    const { title, author, isbn, year, genre } = req.body;

    // Validação de campos obrigatórios
    if (!title || !author || !isbn || year === undefined || !genre) {
      throw new BadRequestError(
        'Campos obrigatórios: title, author, isbn, year, genre. Todos devem ser fornecidos.'
      );
    }

    // Validação de tipos
    if (typeof title !== 'string' || title.trim().length === 0) {
      throw new BadRequestError('O campo "title" deve ser uma string não vazia.');
    }
    if (typeof author !== 'string' || author.trim().length === 0) {
      throw new BadRequestError('O campo "author" deve ser uma string não vazia.');
    }
    if (typeof isbn !== 'string' || isbn.trim().length === 0) {
      throw new BadRequestError('O campo "isbn" deve ser uma string não vazia.');
    }
    if (!Number.isInteger(year) || year < 0 || year > new Date().getFullYear() + 1) {
      throw new BadRequestError(
        `O campo "year" deve ser um ano válido (inteiro entre 0 e ${new Date().getFullYear() + 1}).`
      );
    }
    if (typeof genre !== 'string' || genre.trim().length === 0) {
      throw new BadRequestError('O campo "genre" deve ser uma string não vazia.');
    }

    // Verifica unicidade do ISBN
    const isbnExists = books.some((b) => b.isbn === isbn);
    if (isbnExists) {
      throw new ConflictError(`Já existe um livro com o ISBN "${isbn}".`);
    }

    // Cria o novo livro
    const newBook = {
      id: getNextId(),
      title: title.trim(),
      author: author.trim(),
      isbn: isbn.trim(),
      year,
      genre: genre.trim(),
    };

    books.push(newBook);

    // 201 Created + Location header (convenção REST para recursos criados)
    res.status(201).json({
      data: newBook,
      message: 'Livro criado com sucesso.',
    });
  })
);

/**
 * PUT /books/:id
 * Atualiza completamente um livro existente (substituição total).
 *
 * Diferença entre PUT e PATCH:
 *   - PUT substitui o recurso inteiro; todos os campos devem ser enviados.
 *   - PATCH atualizaria apenas os campos fornecidos (parcial).
 *   Escolhemos PUT aqui por seguir a convenção REST mais estrita para este exemplo.
 *
 * @throws {NotFoundError} Se o livro não for encontrado.
 * @throws {ConflictError} Se o ISBN informado já estiver em uso por outro livro.
 */
router.put(
  '/:id',
  asyncHandler((req, res) => {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      throw new BadRequestError('O parâmetro :id deve ser um número válido.');
    }

    const bookIndex = books.findIndex((b) => b.id === id);

    if (bookIndex === -1) {
      throw new NotFoundError('Livro');
    }

    const { title, author, isbn, year, genre } = req.body;

    // Validação dos campos
    if (!title || !author || !isbn || year === undefined || !genre) {
      throw new BadRequestError(
        'Campos obrigatórios: title, author, isbn, year, genre.'
      );
    }
    if (typeof title !== 'string' || title.trim().length === 0) {
      throw new BadRequestError('O campo "title" deve ser uma string não vazia.');
    }
    if (typeof author !== 'string' || author.trim().length === 0) {
      throw new BadRequestError('O campo "author" deve ser uma string não vazia.');
    }
    if (typeof isbn !== 'string' || isbn.trim().length === 0) {
      throw new BadRequestError('O campo "isbn" deve ser uma string não vazia.');
    }
    if (!Number.isInteger(year) || year < 0 || year > new Date().getFullYear() + 1) {
      throw new BadRequestError(
        `O campo "year" deve ser um ano válido (inteiro entre 0 e ${new Date().getFullYear() + 1}).`
      );
    }
    if (typeof genre !== 'string' || genre.trim().length === 0) {
      throw new BadRequestError('O campo "genre" deve ser uma string não vazia.');
    }

    // Verifica se o ISBN já existe em OUTRO livro (o mesmo ID pode manter seu próprio ISBN)
    const isbnExists = books.some((b) => b.isbn === isbn && b.id !== id);
    if (isbnExists) {
      throw new ConflictError(`Já existe outro livro com o ISBN "${isbn}".`);
    }

    // Atualiza o livro na posição encontrada (mutação direta do array)
    books[bookIndex] = {
      id,
      title: title.trim(),
      author: author.trim(),
      isbn: isbn.trim(),
      year,
      genre: genre.trim(),
    };

    res.json({
      data: books[bookIndex],
      message: 'Livro atualizado com sucesso.',
    });
  })
);

/**
 * DELETE /books/:id
 * Exclui um livro pelo ID.
 *
 * @throws {NotFoundError} Se o livro não for encontrado.
 */
router.delete(
  '/:id',
  asyncHandler((req, res) => {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      throw new BadRequestError('O parâmetro :id deve ser um número válido.');
    }

    const bookIndex = books.findIndex((b) => b.id === id);

    if (bookIndex === -1) {
      throw new NotFoundError('Livro');
    }

    // Remove o livro do array (splice altera o array in-place, O(n))
    const [deletedBook] = books.splice(bookIndex, 1);

    // 204 No Content — padrão REST para deleção sem corpo de resposta
    res.status(204).end();
  })
);

module.exports = router;
```

