## Arquivo 6: `src/routes/stats.js`

```javascript
/**
 * @fileoverview Rotas de estatísticas da API.
 *
 * Endpoint: GET /stats
 * Retorna métricas agregadas sobre o acervo de livros.
 *
 * Exemplo de resposta:
 * {
 *   "total": 3,
 *   "livrosPorGenero": { "Fantasia": 1, "Distopia": 1, "Romance": 1 },
 *   "mediaAnoPublicacao": 1967.33,
 *   "autoresMaisProdutivos": [ ... ]
 * }
 */

const express = require('express');
const router = express.Router();
const { asyncHandler } = require('../middleware/errorHandler');
const { books } = require('../data/books');

/**
 * GET /stats
 * Retorna estatísticas agregadas do acervo de livros.
 *
 * Métricas calculadas:
 *   - total              : número total de livros cadastrados
 *   - livrosPorGenero    : contagem de livros por gênero
 *   - mediaAnoPublicacao : média dos anos de publicação (arredondada para 2 casas)
 *   - livroMaisAntigo    : livro com o menor ano de publicação
 *   - livroMaisRecente   : livro com o maior ano de publicação
 */
router.get(
  '/',
  asyncHandler((req, res) => {
    const total = books.length;

    // Agrupamento por gênero usando reduce (O(n))
    const livrosPorGenero = books.reduce((acc, book) => {
      acc[book.genre] = (acc[book.genre] || 0) + 1;
      return acc;
    }, {});

    // Cálculo da média dos anos de publicação
    const mediaAnoPublicacao =
      total > 0
        ? Math.round((books.reduce((sum, b) => sum + b.year, 0) / total) * 100) / 100
        : 0;

    // Livros mais antigo e mais recente (ordenamos cópia para não mutar o array original)
    const sortedByYear = [...books].sort((a, b) => a.year - b.year);
    const livroMaisAntigo = sortedByYear[0] || null;
    const livroMaisRecente = sortedByYear[total - 1] || null;

    res.json({
      total,
      livrosPorGenero,
      mediaAnoPublicacao,
      livroMaisAntigo: livroMaisAntigo
        ? { title: livroMaisAntigo.title, author: livroMaisAntigo.author, year: livroMaisAntigo.year }
        : null,
      livroMaisRecente: livroMaisRecente
        ? { title: livroMaisRecente.title, author: livroMaisRecente.author, year: livroMaisRecente.year }
        : null,
    });
  })
);

module.exports = router;
```

