## Arquivo 7: `src/app.js`

```javascript
/**
 * @fileoverview Ponto de entrada da aplicação Express.
 *
 * Arquitetura adotada:
 *   1. Configuração do Express (body-parser, JSON)
 *   2. Middlewares globais (CORS, logging básico)
 *   3. Rotas da API (mountadas em /books e /stats)
 *   4. Middleware de tratamento de erros (deve ser o ÚLTIMO middleware)
 *   5. Rota 404 para rotas inexistentes
 *   6. Inicialização do servidor na porta configurada
 *
 * Por que a ordem dos middlewares importa?
 *   - O Express executa middlewares em sequência (fila FIFO).
 *   - Middlewares de erro só são chamados quando `next(err)` é invocado.
 *   - Colocar o errorHandler antes das rotas faria com que erros não fossem capturados corretamente.
 */

const express = require('express');
const booksRoutes = require('./routes/books');
const statsRoutes = require('./routes/stats');
const { errorHandler } = require('./middleware/errorHandler');
const { AppError } = require('./errors/CustomError');

const app = express();
const PORT = process.env.PORT || 3000;

// ============================================================
// Middlewares globais
// ============================================================

/**
 * Parser do corpo da requisição em JSON.
 * Limitamos a 10kb para evitar payloads excessivamente grandes.
 */
app.use(express.json({ limit: '10kb' }));

/**
 * Middleware CORS simplificado.
 * Em produção, substituir por `cors` package com configurações específicas de origem.
 */
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', '*');
  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');

  // Responde imediatamente a requisições OPTIONS (preflight CORS)
  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }
  next();
});

/**
 * Logger básico de requisições (estilo simplified Apache Combined Log).
 * Ajuda a depurar problemas de tráfego e performance.
 */
app.use((req, res, next) => {
  const start = Date.now();
  // Intercepta o método `res.end` para logar após a resposta ser enviada
  const originalEnd = res.end.bind(res);
  res.end = function (...args) {
    const duration = Date.now() - start;
    console.log(
      `[${new Date().toISOString()}] ${req.method} ${req.originalUrl} → ${res.statusCode} (${duration}ms)`
    );
    originalEnd(...args);
  };
  next();
});

// ============================================================
// Rotas da API
// ============================================================

/**
 * Mount das rotas de livros em /books.
 * O Express prefixa automaticamente: todas as rotas do módulo books.js
 * são acessíveis como /books, /books/:id, etc.
 */
app.use('/books', booksRoutes);

/**
 * Mount das rotas de estatísticas em /stats.
 */
app.use('/stats', statsRoutes);

// ============================================================
// Rota 404 para recursos inexistentes
// ============================================================

/**
 * Middleware que captura requisições para rotas não definidas.
 * Lança um AppError customizado para ser capturado pelo errorHandler global.
 */
app.use((req, res, next) => {
  next(new AppError(`Rota ${req.method} ${req.originalUrl} não encontrada.`, 404));
});

// ============================================================
// Middleware de tratamento de erros (DEVE ser o último middleware)
// ============================================================

app.use(errorHandler);

// ============================================================
// Inicialização do servidor
// ============================================================

app.listen(PORT, () => {
  console.log(`
╔══════════════════════════════════════════════════════╗
║     API de Livros — Servidor rodando na porta ${PORT}   ║
║                                                      ║
║  Endpoints disponíveis:                              ║
║    GET  http://localhost:${PORT}/books               ║
║    GET  http://localhost:${PORT}/books/:id           ║
║    POST http://localhost:${PORT}/books               ║
║    PUT  http://localhost:${PORT}/books/:id           ║
║    DELETE http://localhost:${PORT}/books/:id         ║
║    GET  http://localhost:${PORT}/stats               ║
╚══════════════════════════════════════════════════════╝
  `);
});

module.exports = app;
```

