## File 2: `data/books.js` — In-Memory Data Store

```javascript
/**
 * @fileoverview In-memory data store for books.
 * 
 * WHY IN-MEMORY?
 * For an educational example, an in-memory array avoids the complexity of setting up a database
 * while still demonstrating CRUD operations, filtering, and state management. In production, you'd
 * replace this with a MongoDB/PostgreSQL layer using an ORM like Mongoose or Sequelize.
 * 
 * DATA STRUCTURE CHOICES:
 * - Array of objects: Simple, ordered, easy to iterate for stats/filtering.
 * - Each book has: id (number), title (string), author (string), genre (string),
 *   publishedYear (number), rating (number 1-5). These fields cover common book metadata.
 * - IDs are auto-incremented integers starting from 1 for simplicity and predictability.
 */

// Seed data so the API isn't empty on startup — useful for immediate testing.
const books = [
  {
    id: 1,
    title: "The Great Gatsby",
    author: "F. Scott Fitzgerald",
    genre: "Classic",
    publishedYear: 1925,
    rating: 4.5
  },
  {
    id: 2,
    title: "To Kill a Mockingbird",
    author: "Harper Lee",
    genre: "Fiction",
    publishedYear: 1960,
    rating: 4.8
  },
  {
    id: 3,
    title: "1984",
    author: "George Orwell",
    genre: "Dystopian",
    publishedYear: 1949,
    rating: 4.7
  }
];

// Counter for generating unique IDs. Using a closure-like pattern keeps it encapsulated.
let nextId = 4;

/**
 * Retrieves all books from the in-memory store.
 * @returns {Array<Object>} Array of book objects.
 */
function getAllBooks() {
  return [...books]; // Return a copy to prevent external mutation of the internal array.
}

/**
 * Finds a single book by its numeric ID.
 * @param {number} id - The unique identifier of the book.
 * @returns {Object|undefined} The book object if found, otherwise undefined.
 */
function getBookById(id) {
  return books.find(book => book.id === id);
}

/**
 * Adds a new book to the store and assigns it an auto-incremented ID.
 * @param {Object} bookData - The book data to add (without id).
 * @returns {Object} The newly created book object including its assigned ID.
 */
function createBook(bookData) {
  const newBook = {
    id: nextId++,
    ...bookData
  };
  books.push(newBook);
  return newBook;
}

/**
 * Updates an existing book by ID with the provided fields.
 * @param {number} id - The ID of the book to update.
 * @param {Object} updates - Fields to update (e.g., { title: "New Title" }).
 * @returns {Object|undefined} The updated book object, or undefined if not found.
 */
function updateBook(id, updates) {
  const index = books.findIndex(book => book.id === id);
  if (index === -1) return undefined;

  // Merge existing data with updates — preserves fields not included in the request.
  books[index] = { ...books[index], ...updates };
  return books[index];
}

/**
 * Deletes a book by its ID.
 * @param {number} id - The ID of the book to delete.
 * @returns {boolean} True if the book was found and deleted, false otherwise.
 */
function deleteBook(id) {
  const index = books.findIndex(book => book.id === id);
  if (index === -1) return false;

  books.splice(index, 1);
  return true;
}

/**
 * Computes aggregate statistics across all books.
 * @returns {Object} Statistics including total count, average rating, and genre distribution.
 */
function getStats() {
  const total = books.length;
  if (total === 0) {
    return { total: 0, averageRating: 0, genres: {} };
  }

  // Calculate average rating using reduce for functional clarity.
  const averageRating = books.reduce((sum, book) => sum + book.rating, 0) / total;

  // Count occurrences of each genre to show distribution.
  const genres = {};
  books.forEach(book => {
    genres[book.genre] = (genres[book.genre] || 0) + 1;
  });

  return {
    total,
    averageRating: parseFloat(averageRating.toFixed(2)), // Round to 2 decimal places.
    genres
  };
}

// Export all functions using CommonJS module syntax — standard for Node.js.
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats
};
```

**Key Design Decisions Explained:**  
- **Returning copies (`[...books]`)**: Prevents accidental external modification of the internal state.  
- **Auto-incrementing ID counter**: Simple and predictable; in production you'd use UUIDs or database sequences.  
- **Spread operator for updates**: Allows partial updates (PATCH-like behavior) while preserving other fields.  
- **Stats computed on demand**: Avoids stale data; acceptable for small datasets but would need caching at scale.

