## File 4: `routes/books.js` — Route Handlers

```javascript
/**
 * @fileoverview Express route handlers for book CRUD operations.
 * 
 * ROUTE ORGANIZATION RATIONALE:
 * Keeping routes in a separate file demonstrates separation of concerns — the server.js
 * only wires up middleware and mounts routes, while business logic lives here. This makes
 * it easy to add new endpoints or refactor without touching the main application file.
 * 
 * REST CONVENTIONS FOLLOWED:
 * - GET /books → List all (with optional filtering)
 * - GET /books/:id → Retrieve single resource
 * - POST /books → Create new resource
 * - PUT /books/:id → Full update of existing resource
 * - DELETE /books/:id → Remove resource
 * 
 * ASYNC/AWAIT CHOICE:
 * Using async/await instead of .then() chains improves readability and makes error
 * handling more straightforward with try/catch. Even though this example uses synchronous
 * in-memory operations, the pattern is ready for database integration where async is required.
 */

const express = require("express");
const router = express.Router(); // Create a standalone router instance.

// Import data layer functions and custom errors.
const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook
} = require("../data/books");
const { ValidationError, NotFoundError } = require("../errors/customErrors");

/**
 * GET /books
 * 
 * Retrieves all books with optional filtering by query parameters.
 * 
 * QUERY PARAMETERS (all optional):
 * - genre: Filter by exact genre match (e.g., ?genre=Fiction)
 * - author: Filter by author name substring (case-insensitive, e.g., ?author=orwell)
 * - minRating: Minimum rating threshold 1-5 (e.g., ?minRating=4.0)
 * 
 * EXAMPLE REQUESTS:
 *   curl http://localhost:3000/books
 *   curl "http://localhost:3000/books?genre=Dystopian"
 *   curl "http://localhost:3000/books?author=lee&minRating=4.5"
 */
router.get("/books", (req, res) => {
  try {
    // Destructure query parameters with defaults for safety.
    const { genre, author, minRating } = req.query;

    // Start with all books as the base dataset.
    let filteredBooks = getAllBooks();

    // Apply filters sequentially — each filter narrows the result set.
    if (genre) {
      filteredBooks = filteredBooks.filter(
        book => book.genre.toLowerCase() === genre.toLowerCase()
      );
    }

    if (author) {
      const authorLower = author.toLowerCase();
      filteredBooks = filteredBooks.filter(book =>
        book.author.toLowerCase().includes(authorLower)
      );
    }

    if (minRating) {
      const min = parseFloat(minRating);
      // Validate that minRating is a number between 1 and 5.
      if (isNaN(min) || min < 1 || min > 5) {
        throw new ValidationError("minRating must be a number between 1 and 5");
      }
      filteredBooks = filteredBooks.filter(book => book.rating >= min);
    }

    // Return the (possibly filtered) array with HTTP 200 OK.
    res.json({
      success: true,
      count: filteredBooks.length,
      data: filteredBooks
    });
  } catch (error) {
    // Let the global error handler deal with this — pass control to it.
    next(error);
  }
});

/**
 * GET /books/:id
 * 
 * Retrieves a single book by its numeric ID.
 * 
 * URL PARAMETER:
 * - id: Numeric book identifier (e.g., /books/1)
 * 
 * EXAMPLE REQUESTS:
 *   curl http://localhost:3000/books/1
 *   curl http://localhost:3000/books/999  // Returns 404
 */
router.get("/books/:id", (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);

    // Validate that the ID is a valid integer.
    if (isNaN(id)) {
      throw new ValidationError("Invalid book ID: must be a number");
    }

    const book = getBookById(id);
    if (!book) {
      // Resource not found — throw our custom NotFoundError for consistent handling.
      throw new NotFoundError(`Book with id ${id} not found`);
    }

    res.json({
      success: true,
      data: book
    });
  } catch (error) {
    next(error); // Pass to error-handling middleware.
  }
});

/**
 * POST /books
 * 
 * Creates a new book with the provided JSON body.
 * 
 * REQUIRED FIELDS IN REQUEST BODY:
 * - title (string): Book title, non-empty.
 * - author (string): Author name, non-empty.
 * - genre (string): Genre/category, non-empty.
 * - publishedYear (number): Year between 1000 and current year.
 * - rating (number): Rating between 1.0 and 5.0.
 * 
 * EXAMPLE REQUEST:
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"Dune","author":"Frank Herbert","genre":"Sci-Fi","publishedYear":1965,"rating":4.6}'
 */
router.post("/books", (req, res, next) => {
  try {
    const { title, author, genre, publishedYear, rating } = req.body;

    // Validate all required fields are present and non-empty.
    if (!title || typeof title !== "string" || title.trim() === "") {
      throw new ValidationError("Title is required and must be a non-empty string");
    }
    if (!author || typeof author !== "string" || author.trim() === "") {
      throw new ValidationError("Author is required and must be a non-empty string");
    }
    if (!genre || typeof genre !== "string" || genre.trim() === "") {
      throw new ValidationError("Genre is required and must be a non-empty string");
    }
    if (
      publishedYear === undefined ||
      !Number.isInteger(publishedYear) ||
      publishedYear < 1000 ||
      publishedYear > new Date().getFullYear()
    ) {
      throw new ValidationError(
        "Published year is required and must be an integer between 1000 and current year"
      );
    }
    if (
      rating === undefined ||
      typeof rating !== "number" ||
      rating < 1.0 ||
      rating > 5.0
    ) {
      throw new ValidationError("Rating is required and must be a number between 1.0 and 5.0");
    }

    // Create the book using our data layer — returns the new book with assigned ID.
    const newBook = createBook({
      title: title.trim(),
      author: author.trim(),
      genre: genre.trim(),
      publishedYear,
      rating
    });

    // Return 201 Created (not 200 OK) to indicate a new resource was created.
    res.status(201).json({
      success: true,
      data: newBook
    });
  } catch (error) {
    next(error);
  }
});

/**
 * PUT /books/:id
 * 
 * Fully updates an existing book by ID. All fields must be provided.
 * 
 * NOTE ON PUT vs PATCH:
 * PUT is a full replacement — the client must send all fields. For partial updates,
 * you'd use PATCH instead. This example uses PUT for simplicity and to demonstrate
 * complete field validation.
 * 
 * EXAMPLE REQUEST:
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"The Great Gatsby (Updated)","author":"F. Scott Fitzgerald","genre":"Classic","publishedYear":1925,"rating":4.7}'
 */
router.put("/books/:id", (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      throw new ValidationError("Invalid book ID: must be a number");
    }

    // Check if the book exists before attempting update.
    const existingBook = getBookById(id);
    if (!existingBook) {
      throw new NotFoundError(`Book with id ${id} not found`);
    }

    const { title, author, genre, publishedYear, rating } = req.body;

    // Same validation as POST — required for consistency.
    if (!title || typeof title !== "string" || title.trim() === "") {
      throw new ValidationError("Title is required and must be a non-empty string");
    }
    if (!author || typeof author !== "string" || author.trim() === "") {
      throw new ValidationError("Author is required and must be a non-empty string");
    }
    if (!genre || typeof genre !== "string" || genre.trim() === "") {
      throw new ValidationError("Genre is required and must be a non-empty string");
    }
    if (
      publishedYear === undefined ||
      !Number.isInteger(publishedYear) ||
      publishedYear < 1000 ||
      publishedYear > new Date().getFullYear()
    ) {
      throw new ValidationError(
        "Published year is required and must be an integer between 1000 and current year"
      );
    }
    if (
      rating === undefined ||
      typeof rating !== "number" ||
      rating < 1.0 ||
      rating > 5.0
    ) {
      throw new ValidationError("Rating is required and must be a number between 1.0 and 5.0");
    }

    // Perform the update — returns the updated book object.
    const updatedBook = updateBook(id, {
      title: title.trim(),
      author: author.trim(),
      genre: genre.trim(),
      publishedYear,
      rating
    });

    res.json({
      success: true,
      data: updatedBook
    });
  } catch (error) {
    next(error);
  }
});

/**
 * DELETE /books/:id
 * 
 * Deletes a book by its ID.
 * 
 * EXAMPLE REQUESTS:
 *   curl -X DELETE http://localhost:3000/books/1
 *   curl -X DELETE http://localhost:3000/books/999  // Returns 404
 */
router.delete("/books/:id", (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      throw new ValidationError("Invalid book ID: must be a number");
    }

    // Check existence before deletion for a clear error message.
    const existingBook = getBookById(id);
    if (!existingBook) {
      throw new NotFoundError(`Book with id ${id} not found`);
    }

    // Perform the deletion — returns true if successful.
    const deleted = deleteBook(id);

    // Return 204 No Content for successful deletions (no response body needed).
    res.status(204).send();
  } catch (error) {
    next(error);
  }
});

module.exports = router;
```

**Why Separate Route File?**  
- **Maintainability**: Adding a new resource (e.g., authors) means creating another route file without modifying `server.js`.  
- **Testability**: Routes can be unit-tested independently of the Express app setup.  
- **Readability**: Each file has a single responsibility, making the codebase easier to navigate.

