## File 8: `server.js` — Application Entry Point

```javascript
/**
 * @fileoverview Main Express application server.
 * 
 * SERVER ARCHITECTURE EXPLANATION:
 * This file wires together all the pieces we've built:
 * 1. Express app initialization
 * 2. Built-in middleware (JSON parsing)
 * 3. Custom middleware (request logging)
 * 4. Route mounting
 * 5. Global error handler
 * 
 * MIDDLEWARE ORDER MATTERS:
 * Middleware executes in the order it's added. We place request logging before routes so we
 * can see all incoming requests. The error handler must be last because it catches errors
 * from everything above it.
 */

const express = require("express");
const path = require("path");

// Initialize Express application.
const app = express();

// PORT CONFIGURATION:
// Use environment variable PORT if set (common in deployment platforms like Heroku),
// otherwise default to 3000 for local development.
const PORT = process.env.PORT || 3000;

/**
 * MIDDLEWARE SETUP
 */

// Built-in middleware to parse JSON request bodies.
// This makes req.body available in route handlers.
app.use(express.json());

// Custom middleware for request logging (defined in separate file).
const requestLogger = require("./middleware/requestLogger");
app.use(requestLogger);

/**
 * ROUTE MOUNTING
 */

// Import route modules.
const bookRoutes = require("./routes/books");
const statsRoutes = require("./routes/stats");

// Mount routes on their respective paths.
// All book CRUD operations will be available under /books.
app.use("/", bookRoutes);

// Stats endpoint at /stats.
app.use("/", statsRoutes);

/**
 * ROOT ENDPOINT
 * 
 * Provides a simple welcome message and API documentation link.
 */
app.get("/", (req, res) => {
  res.json({
    success: true,
    message: "Welcome to the Book REST API!",
    endpoints: {
      books: {
        list: "GET /books",
        getById: "GET /books/:id",
        create: "POST /books",
        update: "PUT /books/:id",
        delete: "DELETE /books/:id"
      },
      stats: "GET /stats"
    }
  });
});

/**
 * 404 HANDLER
 * 
 * Catches requests to undefined routes and returns a 404 response.
 * This must be placed AFTER all route definitions but BEFORE the error handler.
 */
app.use((req, res, next) => {
  const { NotFoundError } = require("./errors/customErrors");
  next(new NotFoundError(`Route ${req.method} ${req.url} not found`));
});

/**
 * GLOBAL ERROR HANDLER
 * 
 * Must have 4 parameters (err, req, res, next) to be recognized as error-handling middleware.
 * This catches all errors thrown in routes and middleware.
 */
const errorHandler = require("./middleware/errorHandler");
app.use(errorHandler);

/**
 * SERVER STARTUP
 */
app.listen(PORT, () => {
  console.log(`Book REST API is running on http://localhost:${PORT}`);
  console.log(`Try these endpoints:`);
  console.log(`  GET  http://localhost:${PORT}/`);
  console.log(`  GET  http://localhost:${PORT}/books`);
  console.log(`  POST http://localhost:${PORT}/books`);
  console.log(`  GET  http://localhost:${PORT}/stats`);
});

module.exports = app;
```

**Why This Structure?**  
- **Single Responsibility**: Each file handles one concern (routes, errors, data, middleware).  
- **Middleware Chain**: Express processes middleware in order — logging → routes → 404 handler → error handler.  
- **Environment Variables**: Using `process.env.PORT` makes the app deployable to platforms that assign ports dynamically.

