## Arquivo 3: `src/middleware/errorHandler.js`

```javascript
/**
 * ============================================================
 * MIDDLEWARE DE TRATAMENTO DE ERROS
 * ============================================================
 *
 * POR QUE um middleware dedicado?
 * --------------------------------
 * Express permite definir middlewares com 4 parâmetros (err, req, res, next).
 * Quando qualquer rota ou middleware chama next(err), o fluxo pula para
 * este handler. Isso centraliza a lógica de resposta de erro, evitando
 * repetição de try/catch em cada rota.
 *
 * Padrão adotado: Resposta JSON consistente com { error: { message, statusCode } }.
 * Em desenvolvimento, incluímos o stack trace para facilitar debugging.
 */

const { InternalError } = require('../errors');

/**
 * Middleware global de tratamento de erros.
 *
 * @param {Error} err - Instância de erro capturada pelo Express
 * @param {import('express').Request} req - Objeto de requisição
 * @param {import('express').Response} res - Objeto de resposta
 * @param {import('express').NextFunction} next - Função next (não usada aqui)
 */
function errorHandler(err, req, res, next) {
  // Determina o status: usa o do erro customizado ou 500 como fallback
  const statusCode = err.statusCode || 500;

  // Em desenvolvimento, incluímos o stack trace para debugging
  const stack = process.env.NODE_ENV === 'development' ? err.stack : undefined;

  // Monta a resposta JSON padronizada
  const response = {
    error: {
      message: err.message,
      statusCode,
    },
  };

  // Adiciona stack trace apenas em desenvolvimento (segurança: não vazar internals em produção)
  if (stack) {
    response.error.stack = stack;
  }

  // Log do erro no servidor para fins de monitoramento
  // Em produção, erros operacionais (4xx) são menos críticos e podem ser logados separadamente
  if (!err.isOperational) {
    console.error('[ERRO DO SERVIDOR]', err);
  } else {
    // Erros operacionais são logados de forma mais leve
    console.warn(`[ERRO OPERACIONAL] ${statusCode} - ${err.message}`);
  }

  // Envia a resposta com o status apropriado
  res.status(statusCode).json(response);
}

module.exports = errorHandler;
```

**Explicação:** O middleware de erro é registrado *depois* de todas as rotas (convenção Express). Ele intercepta erros passados via `next(err)`. A verificação `process.env.NODE_ENV` protege a segurança: em produção, stack traces não devem ser expostos ao cliente pois revelam estrutura interna do servidor.

