## Arquivo 5: `src/routes/books.js`

```javascript
/**
 * ============================================================
 * ROTAS DE LIVROS — CRUD COMPLETO
 * ============================================================
 *
 * PADRÕES REST ADOTADOS:
 * ----------------------
 *   GET    /books          → Listar todos (com filtragem opcional)
 *   GET    /books/:id      → Obter um específico
 *   POST   /books          → Criar novo
 *   PUT    /books/:id      → Atualizar completo (replace)
 *   DELETE /books/:id      → Excluir
 *
 * POR QUE PUT e não PATCH?
 * -------------------------
 * PUT substitui o recurso inteiro; o cliente deve enviar todos os campos.
 * PATCH atualiza apenas campos específicos. Para este exemplo, PUT é mais
 * simples de validar (todos os campos obrigatórios devem estar presentes).
 *
 * PADRÃO ASYNC/AWAIT:
 * --------------------
 * Usamos async/await porque:
 *   1. Código assíncrono fica linear e legível (sem callbacks aninhados)
 *   2. Erros podem ser capturados com try/catch tradicional
 *   3. É o padrão moderno do ecossistema Node.js desde ES2017
 */

const { books, nextId } = require('../data/books');
const {
  BadRequestError,
  NotFoundError,
  ConflictError,
} = require('../errors');

/**
 * ============================================================
 * GET /books — Listar todos os livros com filtragem opcional
 * ============================================================
 *
 * Query parameters suportados:
 *   - author: filtra por autor (case-insensitive, partial match)
 *   - genre:  filtra por gênero (case-insensitive, exato)
 *   - year:   filtra por ano de publicação (número exato)
 *   - search: busca por título ou autor (partial match, case-insensitive)
 *
 * Exemplo de uso:
 *   GET /books?author=tolkien&genre=fantasia
 *   GET /books?search=hobbit
 *
 * Resposta de sucesso (200):
 *   { "data": [ {...}, {...} ], "total": 2 }
 */

/**
 * @param {import('express').Request} req - Requisição HTTP com query params
 * @param {import('express').Response} res - Resposta HTTP
 */
function listBooks(req, res) {
  // Começamos com todos os livros e aplicamos filtros sequencialmente
  let result = [...books]; // Spread cria cópia para não mutar o array original

  // Filtro por autor: converte para lowercase para comparação case-insensitive
  if (req.query.author) {
    const authorFilter = req.query.author.toLowerCase();
    result = result.filter((book) =>
      book.author.toLowerCase().includes(authorFilter)
    );
  }

  // Filtro por gênero: correspondência exata, case-insensitive
  if (req.query.genre) {
    const genreFilter = req.query.genre.toLowerCase();
    result = result.filter(
      (book) => book.genre && book.genre.toLowerCase() === genreFilter
    );
  }

  // Filtro por ano: converte string da query para número
  if (req.query.year) {
    const yearFilter = parseInt(req.query.year, 10);
    result = result.filter((book) => book.year === yearFilter);
  }

  // Busca textual: procura em título E autor simultaneamente
  if (req.query.search) {
    const searchFilter = req.query.search.toLowerCase();
    result = result.filter(
      (book) =>
        book.title.toLowerCase().includes(searchFilter) ||
        book.author.toLowerCase().includes(searchFilter)
    );
  }

  // Resposta padronizada com dados e metadados de paginação
  res.json({
    data: result,
    total: result.length,
    // Metadados úteis para o cliente entender o contexto da resposta
    meta: {
      timestamp: new Date().toISOString(),
      filtersApplied: Object.keys(req.query),
    },
  });
}

/**
 * ============================================================
 * GET /books/:id — Obter livro por ID
 * ============================================================
 *
 * Exemplo de uso:
 *   GET /books/1
 *
 * Resposta de sucesso (200):
 *   { "data": {...} }
 *
 * Resposta de erro (404):
 *   { "error": { "message": "Livro com ID 999 não encontrado", "statusCode": 404 } }
 */

/**
 * @param {import('express').Request} req - Requisição com params.id
 * @param {import('express').Response} res - Resposta HTTP
 * @param {import('express').NextFunction} next - Função next para propagação de erros
 */
function getBookById(req, res, next) {
  // Converte ID de string (req.params são sempre strings) para número
  const id = parseInt(req.params.id, 10);

  // Busca linear no array — eficiente para arrays pequenos (< 1000 elementos)
  // Para grandes volumes, usaríamos um Map ou índice em banco de dados
  const book = books.find((b) => b.id === id);

  if (!book) {
    // Propaga o erro para o middleware de tratamento (errorHandler)
    // Isso é preferível a res.status().json() direto porque centraliza o formato da resposta
    return next(new NotFoundError('Livro', id));
  }

  res.json({ data: book });
}

/**
 * ============================================================
 * POST /books — Criar novo livro
 * ============================================================
 *
 * Corpo esperado (JSON):
 *   { "title": "O Senhor dos Anéis", "author": "J.R.R. Tolkien", "year": 1954, "genre": "fantasia" }
 *
 * Campos obrigatórios: title, author, year
 * Campo opcional: genre
 *
 * Exemplo curl:
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"1984","author":"George Orwell","year":1949,"genre":"distopia"}'
 */

/**
 * @param {import('express').Request} req - Requisição com body do livro
 * @param {import('express').Response} res - Resposta HTTP
 * @param {import('express').NextFunction} next - Função next para propagação de erros
 */
function createBook(req, res, next) {
  const { title, author, year, genre } = req.body;

  // Validação: campos obrigatórios devem estar presentes e não vazios
  if (!title || !author || !year) {
    return next(
      new BadRequestError('Campos obrigatórios: title, author, year')
    );
  }

  // Validação adicional: ano deve ser um número inteiro positivo
  const yearNum = parseInt(year, 10);
  if (isNaN(yearNum) || yearNum < 0 || yearNum > new Date().getFullYear() + 1) {
    return next(
      new BadRequestError('Year must be a valid positive integer')
    );
  }

  // Validação: título e autor devem ter pelo menos 1 caractere após trim
  const trimmedTitle = title.trim();
  const trimmedAuthor = author.trim();

  if (trimmedTitle.length === 0 || trimmedAuthor.length === 0) {
    return next(new BadRequestError('Title and author must not be empty'));
  }

  // Gera ID único usando o contador e incrementa para a próxima inserção
  const id = nextId++;

  // Cria o objeto livro com timestamps automáticos
  const now = new Date().toISOString();
  const book = {
    id,
    title: trimmedTitle,
    author: trimmedAuthor,
    year: yearNum,
    genre: genre ? genre.trim().toLowerCase() : null, // Normaliza gênero para lowercase
    createdAt: now,
    updatedAt: now,
  };

  // Empurra para o array — operação O(1) no final do array
  books.push(book);

  // Status 201 (Created) indica que um novo recurso foi criado com sucesso
  // Localização do novo recurso no header Location (convenção HTTP/REST)
  res.status(201).json({
    data: book,
    meta: {
      message: 'Livro criado com sucesso',
      location: `/books/${id}`,
    },
  });
}

/**
 * ============================================================
 * PUT /books/:id — Atualizar livro existente (substituição completa)
 * ============================================================
 *
 * Exemplo curl:
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"Admirável Mundo Novo","author":"Aldous Huxley","year":1932,"genre":"distopia"}'
 */

/**
 * @param {import('express').Request} req - Requisição com params.id e body atualizado
 * @param {import('express').Response} res - Resposta HTTP
 * @param {import('express').NextFunction} next - Função next para propagação de erros
 */
function updateBook(req, res, next) {
  const id = parseInt(req.params.id, 10);
  const index = books.findIndex((b) => b.id === id);

  if (index === -1) {
    return next(new NotFoundError('Livro', id));
  }

  const { title, author, year, genre } = req.body;

  // Validação dos campos obrigatórios
  if (!title || !author || !year) {
    return next(
      new BadRequestError('Campos obrigatórios: title, author, year')
    );
  }

  const trimmedTitle = title.trim();
  const trimmedAuthor = author.trim();
  const yearNum = parseInt(year, 10);

  if (trimmedTitle.length === 0 || trimmedAuthor.length === 0) {
    return next(new BadRequestError('Title and author must not be empty'));
  }

  // Atualiza o objeto no array usando splice para manter a referência do array
  const updatedBook = {
    id,
    title: trimmedTitle,
    author: trimmedAuthor,
    year: yearNum,
    genre: genre ? genre.trim().toLowerCase() : null,
    createdAt: books[index].createdAt, // Preserva timestamp de criação original
    updatedAt: new Date().toISOString(), // Atualiza timestamp de modificação
  };

  // Substitui o elemento no índice encontrado
  books.splice(index, 1, updatedBook);

  res.json({
    data: updatedBook,
    meta: { message: 'Livro atualizado com sucesso' },
  });
}

/**
 * ============================================================
 * DELETE /books/:id — Excluir livro por ID
 * ============================================================
 *
 * Exemplo curl:
 *   curl -X DELETE http://localhost:3000/books/1
 */

/**
 * @param {import('express').Request} req - Requisição com params.id
 * @param {import('express').Response} res - Resposta HTTP
 * @param {import('express').NextFunction} next - Função next para propagação de erros
 */
function deleteBook(req, res, next) {
  const id = parseInt(req.params.id, 10);
  const index = books.findIndex((b) => b.id === id);

  if (index === -1) {
    return next(new NotFoundError('Livro', id));
  }

  // Remove o elemento do array — splice retorna array com o elemento removido
  const [removedBook] = books.splice(index, 1);

  // Status 200 com corpo contendo o recurso removido (útil para confirmação)
  // Alternativa: 204 No Content (sem corpo) também seria válida em REST puro
  res.json({
    data: removedBook,
    meta: { message: 'Livro excluído com sucesso' },
  });
}

// Exporta todas as funções de rota como módulo
module.exports = {
  listBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
};
```

**Explicação:** Cada handler segue o padrão `(req, res, next)`. Erros são propagados via `next(err)` em vez de responder diretamente, permitindo que o middleware de erro padronize todas as respostas. A validação é feita antes de qualquer operação no array, seguindo o princípio *fail fast*.

