## Arquivo 6: `src/routes/stats.js`

```javascript
/**
 * ============================================================
 * ROTAS DE ESTATÍSTICAS
 * ============================================================
 *
 * GET /stats — Retornar estatísticas agregadas sobre os livros
 *
 * As estatísticas são calculadas em tempo real a partir do array,
 * então refletem sempre o estado atual da memória.
 *
 * Exemplo de resposta:
 *   {
 *     "data": {
 *       "totalBooks": 5,
 *       "totalAuthors": 4,
 *       "averageYear": 1978,
 *       "genres": { "fantasia": 2, "ficcao": 1, ... },
 *       "oldestBook": { "title": "...", "year": 1949 },
 *       "newestBook": { "title": "...", "year": 2023 }
 *     }
 *   }
 */

const { books } = require('../data/books');

/**
 * @param {import('express').Request} req - Requisição HTTP
 * @param {import('express').Response} res - Resposta HTTP
 */
function getStats(req, res) {
  // Se não há livros, retorna estatísticas zeradas
  if (books.length === 0) {
    return res.json({
      data: {
        totalBooks: 0,
        totalAuthors: 0,
        averageYear: null,
        genres: {},
        oldestBook: null,
        newestBook: null,
      },
    });
  }

  // Calcula autores únicos usando Set (estrutura que elimina duplicatas automaticamente)
  const uniqueAuthors = new Set(books.map((book) => book.author));

  // Calcula média dos anos com redução do array
  const totalYear = books.reduce((sum, book) => sum + book.year, 0);
  const averageYear = Math.round(totalYear / books.length);

  // Conta ocorrências por gênero usando reduce (acumulador é um objeto)
  const genres = books.reduce((acc, book) => {
    if (book.genre) {
      acc[book.genre] = (acc[book.genre] || 0) + 1;
    }
    return acc;
  }, {});

  // Encontra livro mais antigo e mais recente por ano
  const oldestBook = books.reduce(
    (min, book) => (book.year < min.year ? book : min),
    books[0]
  );
  const newestBook = books.reduce(
    (max, book) => (book.year > max.year ? book : max),
    books[0]
  );

  res.json({
    data: {
      totalBooks: books.length,
      totalAuthors: uniqueAuthors.size,
      averageYear,
      genres,
      oldestBook,
      newestBook,
    },
    meta: {
      timestamp: new Date().toISOString(),
      note: 'Estatísticas calculadas em tempo real a partir do array de livros',
    },
  });
}

module.exports = { getStats };
```

**Explicação:** As estatísticas usam métodos funcionais do Array (`map`, `reduce`, `Set`) que são expressivos e imutáveis (não alteram o array original). O `Set` para autores únicos é mais eficiente que filtrar manualmente com `indexOf`.

