## Arquivo 7: `src/app.js`

```javascript
/**
 * ============================================================
 * APP PRINCIPAL — Configuração do Servidor Express
 * ============================================================
 *
 * ESTRUTURA DE MIDDLEWARE (ordem importa!):
 * ------------------------------------------
 *   1. body-parser     → Parseia JSON no corpo da requisição
 *   2. Rotas           → Handlers de cada endpoint
 *   3. errorHandler    → Captura erros propagados via next(err)
 *      ^ Deve ser o ÚLTIMO middleware registrado
 *
 * POR QUE essa ordem?
 * --------------------
 * O Express executa middlewares na ordem em que são registrados.
 * O errorHandler deve vir por último para capturar erros de TODOS
 * os middlewares e rotas anteriores. Se colocado antes, não capturaria
 * erros das rotas registradas após ele.
 */

const express = require('express');
const { listBooks, getBookById, createBook, updateBook, deleteBook } = require('./routes/books');
const { getStats } = require('./routes/stats');
const errorHandler = require('./middleware/errorHandler');

// Inicializa a aplicação Express
const app = express();

// Configura a porta: usa variável de ambiente ou padrão 3000
// Convenção: PORT é o padrão em aplicações Heroku/Cloud
const PORT = process.env.PORT || 3000;

/**
 * ============================================================
 * MIDDLEWARES GLOBAIS
 * ============================================================
 */

// Middleware para parsear JSON no corpo das requisições.
// Sem isso, req.body seria undefined em POST/PUT.
// express.json() limita o tamanho a 100KB por padrão (segurança).
app.use(express.json());

// Middleware de logging simples para debug — registra método, URL e timestamp
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next(); // Passa o controle para o próximo middleware/rota
});

/**
 * ============================================================
 * ROTAS DA API
 * ============================================================
 */

// GET /books — Listar todos os livros (com filtragem via query params)
app.get('/books', listBooks);

// GET /books/:id — Obter livro específico por ID numérico
app.get('/books/:id', getBookById);

// POST /books — Criar novo livro (corpo JSON com title, author, year, genre)
app.post('/books', createBook);

// PUT /books/:id — Atualizar livro existente (substituição completa)
app.put('/books/:id', updateBook);

// DELETE /books/:id — Excluir livro por ID
app.delete('/books/:id', deleteBook);

// GET /stats — Estatísticas agregadas sobre o acervo de livros
app.get('/stats', getStats);

/**
 * ============================================================
 * ROTA 404 PARA RECURSOS NÃO ENCONTRADOS
 * ============================================================
 *
 * Esta rota captura qualquer URL que não corresponda a nenhuma
 * rota definida acima. Deve vir DEPOIS de todas as rotas e
 * ANTES do middleware de erro.
 */
app.use((req, res, next) => {
  // Usamos next() com um erro para reaproveitar o errorHandler
  next(new Error(`Rota ${req.method} ${req.url} não encontrada`));
});

/**
 * ============================================================
 * MIDDLEWARE DE TRATAMENTO DE ERROS (SEMPRE POR ÚLTIMO)
 * ============================================================
 */
app.use(errorHandler);

/**
 * ============================================================
 * INICIALIZAÇÃO DO SERVIDOR
 * ============================================================
 */
app.listen(PORT, () => {
  console.log(`
╔══════════════════════════════════════════════════════╗
║     API REST de Livros — Servidor Rodando!           ║
║                                                      ║
║   Endereço: http://localhost:${PORT}                  ║
║   Ambiente: ${process.env.NODE_ENV || 'development'}                          ║
║                                                      ║
║   Endpoints disponíveis:                             ║
║     GET    /books          — Listar livros           ║
║     GET    /books/:id      — Obter livro             ║
║     POST   /books          — Criar livro             ║
║     PUT    /books/:id      — Atualizar livro         ║
║     DELETE /books/:id      — Excluir livro           ║
║     GET    /stats          — Estatísticas            ║
╚══════════════════════════════════════════════════════╝
  `);
});

module.exports = app;
```

**Explicação:** O `app.js` orquestra todos os componentes. A ordem dos middlewares é crítica: body-parser primeiro, rotas em seguida, e errorHandler por último. A rota 404 usa `next(err)` para reaproveitar o mesmo handler de erro, mantendo consistência nas respostas.

